import net from 'node:net';

/** Strip IPv4-mapped IPv6 prefix and zone ids. */
export function normalizeIp(ip: string | undefined | null): string {
  if (!ip) return '';
  let s = ip.trim();
  const pct = s.indexOf('%');
  if (pct >= 0) s = s.slice(0, pct);
  if (s.toLowerCase().startsWith('::ffff:') && net.isIPv4(s.slice(7))) s = s.slice(7);
  return s;
}

export interface ParsedCidr {
  family: 'ipv4' | 'ipv6';
  address: string;
  prefix: number;
}

/** Parse "1.2.3.4", "1.2.3.0/24", "2001:db8::/32". Returns null if invalid. */
export function parseCidr(input: string): ParsedCidr | null {
  const s = input.trim();
  const [addrRaw, prefRaw, ...rest] = s.split('/');
  if (rest.length || !addrRaw) return null;
  const addr = normalizeIp(addrRaw);
  const fam = net.isIP(addr);
  if (!fam) return null;
  const max = fam === 4 ? 32 : 128;
  let prefix = max;
  if (prefRaw !== undefined) {
    if (!/^\d{1,3}$/.test(prefRaw)) return null;
    prefix = Number(prefRaw);
    if (prefix < 0 || prefix > max) return null;
  }
  return { family: fam === 4 ? 'ipv4' : 'ipv6', address: addr, prefix };
}

export function makeBlockList(cidrs: string[]): net.BlockList {
  const bl = new net.BlockList();
  for (const c of cidrs) {
    const p = parseCidr(c);
    if (!p) continue;
    bl.addSubnet(p.address, p.prefix, p.family);
  }
  return bl;
}

export function ipInList(bl: net.BlockList, ipRaw: string): boolean {
  const ip = normalizeIp(ipRaw);
  const fam = net.isIP(ip);
  if (!fam) return false;
  try {
    return bl.check(ip, fam === 4 ? 'ipv4' : 'ipv6');
  } catch {
    return false;
  }
}
