import { z } from 'zod';
import type { Suggestion } from '../shared/protocol.js';

export const OPEN_TAG = '<nx-suggestions';
const CLOSE_TAG = '</nx-suggestions>';
const KINDS = ['next', 'fix', 'test', 'deploy', 'explain'] as const;

const itemSchema = z.object({
  label: z.string().trim().min(1).max(120),
  prompt: z.string().trim().min(1).max(4000),
  kind: z.string().optional(),
});

/**
 * Remove complete suggestion blocks; cut at an unterminated opening tag; optionally hold back a trailing
 * partial "<nx-sugg" prefix (for live streaming, where the rest may arrive in a later delta).
 */
export function visibleText(full: string, holdPartial: boolean): string {
  let out = '';
  let i = 0;
  for (;;) {
    const start = full.indexOf(OPEN_TAG, i);
    if (start < 0) {
      out += full.slice(i);
      break;
    }
    out += full.slice(i, start);
    const end = full.indexOf(CLOSE_TAG, start);
    if (end < 0) return out; // unterminated block: hide everything after it
    i = end + CLOSE_TAG.length;
  }
  if (holdPartial) {
    // hold back the longest suffix that is a prefix of OPEN_TAG
    const max = Math.min(OPEN_TAG.length - 1, out.length);
    for (let n = max; n > 0; n--) {
      if (OPEN_TAG.startsWith(out.slice(out.length - n))) return out.slice(0, out.length - n);
    }
  }
  return out;
}

/** Extract suggestions from the LAST complete block in the text. Invalid JSON → []. */
export function parseSuggestions(full: string): Suggestion[] {
  const re = /<nx-suggestions[^>]*>([\s\S]*?)<\/nx-suggestions>/g;
  let m: RegExpExecArray | null;
  let last: string | null = null;
  while ((m = re.exec(full))) last = m[1] ?? null;
  if (last == null) return [];
  let body = last.trim();
  // tolerate ```json fences
  body = body.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '');
  let parsed: unknown;
  try {
    parsed = JSON.parse(body);
  } catch {
    return [];
  }
  if (!Array.isArray(parsed)) return [];
  const items: Suggestion[] = [];
  for (const raw of parsed) {
    const r = itemSchema.safeParse(raw);
    if (!r.success) continue;
    const kind = (KINDS as readonly string[]).includes(r.data.kind ?? '') ? (r.data.kind as Suggestion['kind']) : 'next';
    items.push({ label: r.data.label, prompt: r.data.prompt, kind });
    if (items.length >= 4) break;
  }
  return items;
}

/** Final stored message content: blocks stripped, no hold-back, trimmed. */
export function finalContent(full: string): string {
  return visibleText(full, false).trim();
}
