import fs from 'node:fs';
import path from 'node:path';
import { badRequest, forbidden, notFound } from './errors.js';

export const HEAVY_DIRS = new Set(['node_modules', '.git', 'dist', '.next', '.venv', '__pycache__', '.cache', '.turbo', '.svelte-kit', '.nuxt', 'venv', 'build', 'target', '.parcel-cache']);
/** Dirs excluded from zip downloads (dist/build are kept since users may want them). */
export const ZIP_EXCLUDE = new Set(['node_modules', '.git', '.venv', 'venv', '__pycache__', '.next', '.cache', '.turbo', '.parcel-cache']);

function isInside(root: string, p: string): boolean {
  const rel = path.relative(root, p);
  return rel === '' || (!rel.startsWith('..') && !path.isAbsolute(rel));
}

/** Normalise a client-supplied relative path into a clean posix relative path ('' = root). */
export function cleanRel(input: unknown): string {
  if (input === undefined || input === null) return '';
  if (typeof input !== 'string') throw badRequest('path must be a string');
  if (input.includes('\0')) throw badRequest('Invalid path');
  let s = input.replace(/\\/g, '/').trim();
  s = s.replace(/^\/+/, '');
  const norm = path.posix.normalize(s === '' ? '.' : s);
  if (norm === '.' || norm === './') return '';
  if (norm === '..' || norm.startsWith('../') || path.posix.isAbsolute(norm)) throw forbidden('Path escapes project');
  return norm.replace(/\/+$/, '');
}

export interface Resolved {
  rel: string;
  abs: string;
}

/**
 * Resolve a relative path under root with realpath checks:
 * - lexically inside root
 * - the deepest existing ancestor (or the target itself, if it exists and mustExist/followTarget) realpaths inside root.
 * Symlinks inside the project that point outside are rejected.
 */
export function resolveSafe(root: string, input: unknown, opts: { mustExist?: boolean; allowRoot?: boolean } = {}): Resolved {
  const rel = cleanRel(input);
  if (!rel && opts.allowRoot === false) throw badRequest('Cannot operate on the project root');
  const realRoot = fs.realpathSync(root);
  const abs = path.resolve(realRoot, rel);
  if (!isInside(realRoot, abs)) throw forbidden('Path escapes project');
  // Walk up to the deepest existing path and realpath it.
  let probe = abs;
  for (;;) {
    let st: fs.Stats | null = null;
    try {
      st = fs.lstatSync(probe);
    } catch {
      st = null;
    }
    if (st) {
      const real = fs.realpathSync(probe);
      if (!isInside(realRoot, real)) throw forbidden('Path escapes project');
      break;
    }
    if (probe === realRoot) break;
    probe = path.dirname(probe);
  }
  if (opts.mustExist && !fs.existsSync(abs)) throw notFound('No such file or directory');
  return { rel, abs };
}

export function sanitizeFilename(name: string): string {
  let s = path.basename(String(name || '').replace(/\\/g, '/'));
  s = s.normalize('NFC').replace(/[\x00-\x1f\x7f/\\:*?"<>|]/g, '_').replace(/^\.+/, '_').trim();
  if (s.length > 180) {
    const ext = path.extname(s).slice(0, 20);
    s = s.slice(0, 180 - ext.length) + ext;
  }
  return s || 'file';
}

/** RFC 6266 Content-Disposition with ASCII fallback. */
export function contentDisposition(kind: 'inline' | 'attachment', filename: string): string {
  const ascii = filename.replace(/[^\x20-\x7e]/g, '_').replace(/["\\]/g, '_');
  const encoded = encodeURIComponent(filename).replace(/['()*]/g, (c) => '%' + c.charCodeAt(0).toString(16).toUpperCase());
  return `${kind}; filename="${ascii}"; filename*=UTF-8''${encoded}`;
}

/** Heuristic binary detection: NUL byte in the first 8 KB, or invalid UTF-8. */
export function looksBinary(buf: Buffer): boolean {
  const sample = buf.subarray(0, 8192);
  if (sample.includes(0)) return true;
  try {
    new TextDecoder('utf-8', { fatal: true }).decode(sample.length < buf.length ? trimPartialUtf8(sample) : sample);
    return false;
  } catch {
    return true;
  }
}

function trimPartialUtf8(b: Buffer): Buffer {
  // Avoid false positives when the 8 KB window cuts a multibyte sequence.
  let end = b.length;
