    else this.db.prepare(`DELETE FROM sessions WHERE user_id = ?`).run(userId);
  }

  purgeExpired() {
    this.db.prepare(`DELETE FROM sessions WHERE expires_at < ?`).run(now());
  }
}

// ---------- permissions ----------
export type EffectiveRole = ProjectRole | 'admin';
const RANK: Record<EffectiveRole, number> = { viewer: 1, editor: 2, owner: 3, admin: 4 };

export function projectRole(db: DB, user: Pick<UserRow, 'id' | 'role'>, projectId: string): EffectiveRole | null {
  if (user.role === 'admin') return 'admin';
  const r = db.prepare(`SELECT role FROM project_members WHERE project_id = ? AND user_id = ?`).get(projectId, user.id) as
    | { role: ProjectRole }
    | undefined;
  return r?.role ?? null;
}

export function hasRole(role: EffectiveRole | null, min: ProjectRole): boolean {
  return !!role && RANK[role] >= RANK[min];
}

export interface ProjectRow {
  id: string;
  slug: string;
  name: string;
  description: string;
  color: string;
  icon: string;
  preview_port: number;
  preview_command: string | null;
  preview_strip: number;
  links: string;
  created_by: string | null;
  created_at: number;
  last_active_at: number | null;
  archived: number;
}

/** Load a project and check the user's permission. Non-members get 404 (don't leak existence). */
export function requireProject(db: DB, user: UserRow, projectId: string, min: ProjectRole): { project: ProjectRow; role: EffectiveRole } {
  const project = db.prepare(`SELECT * FROM projects WHERE id = ?`).get(projectId) as ProjectRow | undefined;
  if (!project) throw notFound('Project not found');
  const role = projectRole(db, user, project.id);
  if (!role) throw notFound('Project not found');
  if (!hasRole(role, min)) throw forbidden(`Requires ${min} permission on this project`);
  return { project, role };
}

// ---------- request helpers ----------
declare module 'fastify' {
  interface FastifyRequest {
    user: UserRow | null;
    clientIp: string;
  }
}

export function requireUser(req: FastifyRequest): UserRow {
  if (!req.user) throw unauthorized();
  return req.user;
}
export function requireAdmin(req: FastifyRequest): UserRow {
  const u = requireUser(req);
  if (u.role !== 'admin') throw forbidden('Admin only');
  return u;
}

export function setSessionCookie(reply: FastifyReply, token: string, secure: boolean) {
  reply.setCookie(SESSION_COOKIE, token, {
    httpOnly: true,
    secure,
    sameSite: 'lax',
    path: '/',
    maxAge: Math.floor(SESSION_TTL_MS / 1000),
  });
}
export function clearSessionCookie(reply: FastifyReply, secure: boolean) {
  reply.clearCookie(SESSION_COOKIE, { path: '/', httpOnly: true, secure, sameSite: 'lax' });
}

