import chokidar, { type FSWatcher } from 'chokidar';
import path from 'node:path';
import fs from 'node:fs';
import type { FastifyBaseLogger } from 'fastify';
import type { Hub } from './hub.js';
import { HEAVY_DIRS } from './lib/safepath.js';
import type { FileChangeKind } from './shared/protocol.js';

const DEBOUNCE_MS = 150;

interface Watch {
  watcher: FSWatcher;
  pending: Map<string, FileChangeKind>;
  timer: NodeJS.Timeout | null;
}

/** One chokidar watcher per subscribed project; started on first WS subscriber, closed when none remain. */
export class Watchers {
  private watches = new Map<string, Watch>();

  constructor(
    private hub: Hub,
    private projectsDir: string,
    private resolveSlug: (projectId: string) => string | null,
    private log: FastifyBaseLogger,
  ) {}

  start(projectId: string) {
    if (this.watches.has(projectId)) return;
    const slug = this.resolveSlug(projectId);
    if (!slug) return;
    const root = path.join(this.projectsDir, slug);
    if (!fs.existsSync(root)) return;
    const watcher = chokidar.watch(root, {
      ignoreInitial: true,
      followSymlinks: false,
      depth: 30,
      ignored: (p: string) => {
        const rel = path.relative(root, p);
        if (!rel) return false;
        return rel.split(path.sep).some((seg) => HEAVY_DIRS.has(seg));
      },
    });
    const w: Watch = { watcher, pending: new Map(), timer: null };
    const onEvent = (kind: FileChangeKind) => (abs: string) => {
      const rel = path.relative(root, abs).split(path.sep).join('/');
      if (!rel || rel.startsWith('..')) return;
      w.pending.set(rel, kind);
      if (!w.timer)
        w.timer = setTimeout(() => {
          w.timer = null;
          const items = [...w.pending];
          w.pending.clear();
          for (const [p, k] of items) this.hub.broadcastProject(projectId, { t: 'file_change', projectId, path: p, kind: k });
        }, DEBOUNCE_MS);
    };
    for (const k of ['add', 'change', 'unlink', 'addDir', 'unlinkDir'] as const) watcher.on(k, onEvent(k));
    watcher.on('error', (err) => this.log.warn({ projectId, err: (err as Error).message }, 'watcher error'));
    this.watches.set(projectId, w);
  }

  stop(projectId: string) {
    const w = this.watches.get(projectId);
    if (!w) return;
    if (w.timer) clearTimeout(w.timer);
    void w.watcher.close();
    this.watches.delete(projectId);
  }

  stopAll() {
    for (const id of [...this.watches.keys()]) this.stop(id);
  }

  isWatching(projectId: string) {
    return this.watches.has(projectId);
  }
}

