cat > iprules.ts <<'EOF'
import type net from 'node:net';
import type { DB } from './db.js';
import { ipInList, makeBlockList } from './lib/ip.js';

export interface IpRuleRow {
  id: string;
  kind: 'allow' | 'block';
  cidr: string;
  note: string | null;
  created_by: string | null;
  created_at: number;
}

/** Cached allow/block CIDR lists. If any allow rule exists, only matching IPs may access. Block always wins. */
export class IpRules {
  private allow: net.BlockList | null = null;
  private block: net.BlockList | null = null;
  private hasAllow = false;
  private loaded = false;

  constructor(private db: DB) {}

  list(): IpRuleRow[] {
    return this.db.prepare(`SELECT * FROM ip_rules ORDER BY created_at`).all() as IpRuleRow[];
  }

  invalidate() {
    this.loaded = false;
  }

  private load() {
    const rules = this.list();
    const allow = rules.filter((r) => r.kind === 'allow').map((r) => r.cidr);
    const block = rules.filter((r) => r.kind === 'block').map((r) => r.cidr);
    this.allow = makeBlockList(allow);
    this.block = makeBlockList(block);
    this.hasAllow = allow.length > 0;
    this.loaded = true;
  }

  isAllowed(ip: string): boolean {
    if (!this.loaded) this.load();
    if (this.block && ipInList(this.block, ip)) return false;
    if (this.hasAllow && this.allow && !ipInList(this.allow, ip)) return false;
    return true;
  }

  /** Would `ip` be allowed if the rule set were `rules`? */
  static wouldAllow(rules: Pick<IpRuleRow, 'kind' | 'cidr'>[], ip: string): boolean {
    const allow = rules.filter((r) => r.kind === 'allow').map((r) => r.cidr);
    const block = rules.filter((r) => r.kind === 'block').map((r) => r.cidr);
    if (ipInList(makeBlockList(block), ip)) return false;
    if (allow.length && !ipInList(makeBlockList(allow), ip)) return false;
    return true;
  }
}
EOF
cat > dto.ts <<'EOF'
import type { DB } from './db.js';
import { iso, parseJson } from './db.js';
import type { EffectiveRole, ProjectRow } from './auth.js';
import type { Mode, RunStatus, Suggestion } from './shared/protocol.js';
import type { StoredEvent } from './runs.js';

export function projectDTO(p: ProjectRow, myRole: EffectiveRole) {
  return {
    id: p.id,
    slug: p.slug,
    name: p.name,
    description: p.description,
    color: p.color,
    icon: p.icon,
    previewPort: p.preview_port,
    previewCommand: p.preview_command,
    previewStrip: !!p.preview_strip,
    links: parseJson<string[]>(p.links, []),
    archived: !!p.archived,
    createdAt: iso(p.created_at)!,
    lastActiveAt: iso(p.last_active_at),
    myRole,
  };
}

export interface ConversationRow {
  id: string;
  project_id: string;
  title: string;
  claude_session_id: string | null;
  model: string;
  mode: Mode;
  created_by: string | null;
  created_at: number;
  updated_at: number;
}
export function conversationDTO(c: ConversationRow) {
  return {
    id: c.id,
    projectId: c.project_id,
    title: c.title,
    claudeSessionId: c.claude_session_id,
    model: c.model,
    mode: c.mode,
    createdAt: iso(c.created_at)!,
    updatedAt: iso(c.updated_at)!,
  };
}

export interface RunRow {
  id: string;
  conversation_id: string;
  project_id: string;
  user_id: string | null;
  status: RunStatus;
  model: string;
  mode: Mode;
  thinking: string;
  started_at: number;
  ended_at: number | null;
  input_tokens: number;
  output_tokens: number;
  cache_read: number;
  cache_write: number;
  cost_usd: number;
  duration_ms: number | null;
  ip: string | null;
  upstream_seq: number;
  error: string | null;
}
export function runDTO(r: RunRow) {
  return {
    id: r.id,
    status: r.status,
    model: r.model,
    mode: r.mode,
    thinking: r.thinking,
    startedAt: iso(r.started_at)!,
    endedAt: iso(r.ended_at),
    inputTokens: r.input_tokens,
