import type net from 'node:net';
import type { DB } from './db.js';
import { ipInList, makeBlockList } from './lib/ip.js';

export interface IpRuleRow {
  id: string;
  kind: 'allow' | 'block';
  cidr: string;
  note: string | null;
  created_by: string | null;
  created_at: number;
}

/** Cached allow/block CIDR lists. If any allow rule exists, only matching IPs may access. Block always wins. */
export class IpRules {
  private allow: net.BlockList | null = null;
  private block: net.BlockList | null = null;
  private hasAllow = false;
  private loaded = false;

  constructor(private db: DB) {}

  list(): IpRuleRow[] {
    return this.db.prepare(`SELECT * FROM ip_rules ORDER BY created_at`).all() as IpRuleRow[];
  }

  invalidate() {
    this.loaded = false;
  }

  private load() {
    const rules = this.list();
    const allow = rules.filter((r) => r.kind === 'allow').map((r) => r.cidr);
    const block = rules.filter((r) => r.kind === 'block').map((r) => r.cidr);
    this.allow = makeBlockList(allow);
    this.block = makeBlockList(block);
    this.hasAllow = allow.length > 0;
    this.loaded = true;
  }

  isAllowed(ip: string): boolean {
    if (!this.loaded) this.load();
    if (this.block && ipInList(this.block, ip)) return false;
    if (this.hasAllow && this.allow && !ipInList(this.allow, ip)) return false;
    return true;
  }

  /** Would `ip` be allowed if the rule set were `rules`? */
  static wouldAllow(rules: Pick<IpRuleRow, 'kind' | 'cidr'>[], ip: string): boolean {
    const allow = rules.filter((r) => r.kind === 'allow').map((r) => r.cidr);
    const block = rules.filter((r) => r.kind === 'block').map((r) => r.cidr);
    if (ipInList(makeBlockList(block), ip)) return false;
    if (allow.length && !ipInList(makeBlockList(allow), ip)) return false;
    return true;
  }
}
