import { RunManager } from './runs.js';
import { Settings } from './settings.js';
import { Watchers } from './watchers.js';
import authRoutes from './routes/auth.js';
import projectRoutes from './routes/projects.js';
import conversationRoutes from './routes/conversations.js';
import uploadRoutes from './routes/uploads.js';
import fileRoutes from './routes/files.js';
import previewRoutes from './routes/preview.js';
import usageRoutes from './routes/usage.js';
import adminRoutes from './routes/admin.js';
import staticRoutes from './routes/static.js';
import { attachWebSocket } from './routes/ws.js';
import { attachPreviewProxy } from './routes/previewProxy.js';

export const MAX_UPLOAD_BYTES = 50 * 1024 * 1024;

const APP_CSP = [
  "default-src 'self'",
  "script-src 'self' 'wasm-unsafe-eval'",
  "worker-src 'self' blob:",
  "style-src 'self' 'unsafe-inline'",
  "img-src 'self' data: blob:",
  "font-src 'self' data:",
  "connect-src 'self' wss: ws:",
  "media-src 'self' blob: data:",
  "frame-src 'self'",
  "frame-ancestors 'self'",
  "base-uri 'self'",
  "form-action 'self'",
  "object-src 'none'",
].join('; ');

export interface BuiltApp {
  app: FastifyInstance;
  ctx: Ctx;
  close: () => Promise<void>;
}

export async function buildApp(cfg: Config, opts: { logger?: boolean } = {}): Promise<BuiltApp> {
  const app = Fastify({
    logger: opts.logger === false ? false : {
      level: cfg.logLevel,
      redact: { paths: ['req.headers.cookie', 'req.headers.authorization', 'body.password', '*.password', '*.token'], remove: true },
    },
    trustProxy: cfg.trustProxy,
    bodyLimit: 6 * 1024 * 1024,
    disableRequestLogging: true,
    genReqId: () => crypto.randomUUID(),
  });

  fs.mkdirSync(cfg.projectsDir, { recursive: true });
  fs.mkdirSync(cfg.uploadsDir, { recursive: true });
  const db = openDb(cfg.dbPath);
  const settings = new Settings(db);
  const sessions = new Sessions(db, cfg.sessionSecret);
  const hub = new Hub(db);
  const cb = new Claudebox(cfg);
  const ipRules = new IpRules(db);
  const runs = new RunManager(db, hub, cb, cfg, settings, app.log);
  const watchers = new Watchers(
    hub,
    cfg.projectsDir,
    (pid) => (db.prepare(`SELECT slug FROM projects WHERE id = ?`).get(pid) as { slug: string } | undefined)?.slug ?? null,
    app.log,
  );
  hub.onProjectSubChange = (pid, on) => (on ? watchers.start(pid) : watchers.stop(pid));

  const auditStmt = db.prepare(`INSERT INTO audit_log(user_id, ip, action, target, meta, ts) VALUES (?,?,?,?,?,?)`);
  const audit: Ctx['audit'] = (req, action, target = null, meta = null, userId) => {
    try {
      auditStmt.run(userId ?? req?.user?.id ?? null, req?.clientIp ?? null, action, target, meta == null ? null : JSON.stringify(meta), now());
    } catch (err) {
      app.log.error({ err }, 'audit insert failed');
    }
  };

  const ctx: Ctx = { cfg, db, log: app.log, settings, sessions, hub, runs, watchers, cb, ipRules, audit };

  await bootstrapAdmin(ctx);

  await app.register(cookie);
  await app.register(multipart, { limits: { fileSize: MAX_UPLOAD_BYTES, files: 10, fields: 20, fieldSize: 64 * 1024 } });
  await app.register(rateLimit, { global: false });

  app.decorateRequest('user', null);
  app.decorateRequest('clientIp', '');

  // ---- request log (async batched) ----
  const reqLogBuf: [number, string, string | null, string, string, number, number][] = [];
  const reqLogStmt = db.prepare(`INSERT INTO request_log(ts, ip, user_id, method, path, status, ms) VALUES (?,?,?,?,?,?,?)`);
  const flushReqLog = () => {
    if (!reqLogBuf.length) return;
    const batch = reqLogBuf.splice(0, reqLogBuf.length);
    try {
      db.transaction(() => {
        for (const r of batch) reqLogStmt.run(...r);
      })();
    } catch (err) {
      app.log.error({ err }, 'request_log flush failed');
    }
  };
  const reqLogTimer = setInterval(flushReqLog, 1000);
  const trimTimer = setInterval(() => {
    try {
      db.prepare(`DELETE FROM request_log WHERE ts < ?`).run(now() - 30 * 86400_000);
      db.prepare(`DELETE FROM audit_log WHERE ts < ?`).run(now() - 365 * 86400_000);
      sessions.purgeExpired();
    } catch (err) {
      app.log.error({ err }, 'trim failed');
    }
  }, 3600_000);
  reqLogTimer.unref();
  trimTimer.unref();

  // ---- hooks ----
  app.addHook('onRequest', async (req, reply) => {
    req.clientIp = normalizeIp(req.ip);
    if (!ipRules.isAllowed(req.clientIp)) {
      reply.code(403).header('content-type', 'application/json').send({ error: { code: 'ip_blocked', message: 'Access denied from your IP address' } });
      return reply;
    }
    const token = req.cookies[SESSION_COOKIE];
    if (token) req.user = sessions.lookup(token);
    const url = req.url;
    if (url.startsWith('/api/') && !['GET', 'HEAD', 'OPTIONS'].includes(req.method)) {
      if (!req.headers['x-requested-with']) {
        reply.code(403).send({ error: { code: 'csrf', message: 'Missing X-Requested-With header' } });
        return reply;
      }
      const origin = req.headers.origin;
      if (origin && origin !== 'null' && !originAllowed(origin, req, cfg)) {
        reply.code(403).send({ error: { code: 'csrf', message: 'Cross-origin request rejected' } });
        return reply;
      }
    }
  });

  app.addHook('onSend', async (req, reply, payload) => {
    reply.header('X-Content-Type-Options', 'nosniff');
    reply.header('Referrer-Policy', 'same-origin');
    if (!req.url.startsWith('/preview/')) {
      if (!reply.hasHeader('Content-Security-Policy')) reply.header('Content-Security-Policy', APP_CSP);
      reply.header('X-Frame-Options', 'SAMEORIGIN');
      reply.header('Permissions-Policy', 'microphone=(self), camera=(), geolocation=(), payment=()');
      reply.header('Cross-Origin-Opener-Policy', 'same-origin');
    }
    if (req.url.startsWith('/api/') && !reply.hasHeader('Cache-Control')) reply.header('Cache-Control', 'no-store');
    return payload;
  });

  app.addHook('onResponse', async (req, reply) => {
    const path = req.url.split('?')[0]!;
    if (path === '/api/health' || path.startsWith('/assets/')) return;
    reqLogBuf.push([now(), req.clientIp, req.user?.id ?? null, req.method, path.slice(0, 300), reply.statusCode, Math.round(reply.elapsedTime * 10) / 10]);
    if (reqLogBuf.length > 500) flushReqLog();
  });

  app.setErrorHandler((err, req, reply) => {
    if (err instanceof HttpError) return reply.code(err.status).send({ error: { code: err.code, message: err.message } });
    if (err instanceof ZodError) {
      const first = err.issues[0];
      const msg = first ? `${first.path.join('.') || 'body'}: ${first.message}` : 'Invalid request';
      return reply.code(400).send({ error: { code: 'invalid_request', message: msg } });
    }
    const e = err as { statusCode?: number; code?: string; message?: string };
    const status = e.statusCode && e.statusCode >= 400 && e.statusCode < 600 ? e.statusCode : 500;
    if (status >= 500) req.log.error({ err }, 'request failed');
    const code =
      status === 413 || e.code === 'FST_REQ_FILE_TOO_LARGE' ? 'too_large' : status === 429 ? 'rate_limited' : status >= 500 ? 'internal' : (e.code ?? 'error').toLowerCase();
    return reply.code(e.code === 'FST_REQ_FILE_TOO_LARGE' ? 413 : status).send({
      error: { code, message: status >= 500 ? 'Internal server error' : e.message ?? 'Error' },
    });
  });

  // ---- routes ----
  app.get('/api/health', async () => ({ ok: true, time: new Date().toISOString() }));
  await app.register(authRoutes(ctx));
  await app.register(projectRoutes(ctx));
  await app.register(conversationRoutes(ctx));
  await app.register(uploadRoutes(ctx));
  await app.register(fileRoutes(ctx));
  await app.register(previewRoutes(ctx));
  await app.register(usageRoutes(ctx));
  await app.register(adminRoutes(ctx));
  attachPreviewProxy(app, ctx);
  await app.register(staticRoutes(ctx));
  attachWebSocket(app, ctx);

  app.addHook('onReady', async () => {
    runs.recoverOrphans();
  });

  const close = async () => {
    clearInterval(reqLogTimer);
    clearInterval(trimTimer);
    runs.shutdown();
    watchers.stopAll();
    for (const c of hub.clients) c.ws.terminate();
    await app.close();
    flushReqLog();
    db.close();
  };
  return { app, ctx, close };
}

function originAllowed(origin: string, req: FastifyRequest, cfg: Config): boolean {
  try {
    const o = new URL(origin);
    if (o.origin === new URL(cfg.publicUrl).origin) return true;
    const host = (req.headers['x-forwarded-host'] as string | undefined) ?? req.headers.host;
    return !!host && o.host === host;
  } catch {
    return false;
  }
}

async function bootstrapAdmin(ctx: Ctx) {
  const { db, cfg } = ctx;
  const count = (db.prepare(`SELECT COUNT(*) AS n FROM users WHERE role = 'admin'`).get() as { n: number }).n;
  if (count > 0 || !cfg.adminEmail || !cfg.adminPassword) {
    if (count === 0) ctx.log.warn('No admin user exists and ADMIN_EMAIL/ADMIN_PASSWORD are not set');
    return;
  }
  const existing = db.prepare(`SELECT id FROM users WHERE email = ?`).get(cfg.adminEmail) as { id: string } | undefined;
  const hash = await hashPassword(cfg.adminPassword);
  if (existing) {
    db.prepare(`UPDATE users SET role = 'admin', disabled = 0, password_hash = ? WHERE id = ?`).run(hash, existing.id);
  } else {
    db.prepare(`INSERT INTO users(id, email, name, password_hash, role, created_at) VALUES (?,?,?,?, 'admin', ?)`).run(
      crypto.randomUUID(), cfg.adminEmail.toLowerCase(), cfg.adminName, hash, now(),
    );
  }
  ctx.log.info({ email: cfg.adminEmail }, 'bootstrapped admin user');
}

