import type { FastifyPluginAsync } from 'fastify';
import { z } from 'zod';
import {
  clearSessionCookie, dummyVerify, hashPassword, LOCKOUT_MS, LOCKOUT_THRESHOLD, requireUser, SESSION_COOKIE,
  setSessionCookie, userDTO, verifyPassword, type UserRow,
} from '../auth.js';
import type { Ctx } from '../ctx.js';
import { now } from '../db.js';
import { HttpError } from '../lib/errors.js';

const loginSchema = z.object({ email: z.string().trim().min(1).max(320), password: z.string().min(1).max(1000) });
const pwSchema = z.object({ currentPassword: z.string().min(1).max(1000), newPassword: z.string().min(8).max(1000) });

export default (ctx: Ctx): FastifyPluginAsync =>
  async (app) => {
    const { db, sessions, cfg } = ctx;

    app.post(
      '/api/auth/login',
      { config: { rateLimit: { max: 10, timeWindow: '5 minutes', keyGenerator: (req) => req.clientIp || req.ip } } },
      async (req, reply) => {
        const { email, password } = loginSchema.parse(req.body);
        const user = db.prepare(`SELECT * FROM users WHERE email = ?`).get(email.toLowerCase()) as UserRow | undefined;
        const fail = (reason: string, code = 'invalid_credentials', msg = 'Invalid email or password') => {
          ctx.audit(req, 'login_failed', email.toLowerCase().slice(0, 320), { reason }, user?.id ?? null);
          throw new HttpError(401, code, msg);
        };
        if (!user) {
          await dummyVerify(password);
          return fail('unknown_email');
        }
        if (user.locked_until && user.locked_until > now()) {
          const mins = Math.ceil((user.locked_until - now()) / 60000);
          return fail('locked', 'locked', `Too many failed attempts. Try again in ${mins} minute${mins === 1 ? '' : 's'}.`);
        }
        const ok = await verifyPassword(user.password_hash, password);
        if (!ok) {
          const failed = user.failed_logins + 1;
          const lock = failed >= LOCKOUT_THRESHOLD ? now() + LOCKOUT_MS : null;
          db.prepare(`UPDATE users SET failed_logins = ?, locked_until = ? WHERE id = ?`).run(lock ? 0 : failed, lock, user.id);
          if (lock) ctx.audit(req, 'account_locked', user.email, { minutes: LOCKOUT_MS / 60000 }, user.id);
          return fail('bad_password');
        }
        if (user.disabled) return fail('disabled', 'disabled', 'This account is disabled');
        db.prepare(`UPDATE users SET failed_logins = 0, locked_until = NULL, last_seen_at = ? WHERE id = ?`).run(now(), user.id);
        const token = sessions.create(user.id, req.clientIp, req.headers['user-agent']);
        setSessionCookie(reply, token, cfg.secureCookies);
        ctx.audit(req, 'login', user.email, null, user.id);
        return { user: userDTO({ ...user, last_seen_at: now() }) };
      },
    );

    app.post('/api/auth/logout', async (req, reply) => {
      const token = req.cookies[SESSION_COOKIE];
      if (req.user) ctx.audit(req, 'logout', req.user.email);
      sessions.destroy(token);
      clearSessionCookie(reply, cfg.secureCookies);
      return { ok: true };
    });

    app.get('/api/auth/me', async (req) => {
      const u = requireUser(req);
      return { user: userDTO(u) };
    });

    app.post(
      '/api/auth/password',
