import type { FastifyPluginAsync } from 'fastify';
import crypto from 'node:crypto';
import fs from 'node:fs';
import path from 'node:path';
import { pipeline } from 'node:stream/promises';
import sharp from 'sharp';
import { request, FormData } from 'undici';
import { projectRole, requireProject, requireUser, type UserRow } from '../auth.js';
import type { Ctx } from '../ctx.js';
import { now } from '../db.js';
import { attachmentDTO, type UploadRow } from '../dto.js';
import { badRequest, forbidden, HttpError, notFound } from '../lib/errors.js';
import { contentDisposition, mimeFromName, sanitizeFilename } from '../lib/safepath.js';

const THUMB = '.thumb.webp';
const THUMBABLE = new Set(['image/png', 'image/jpeg', 'image/webp', 'image/gif', 'image/avif', 'image/tiff', 'image/bmp']);
const ACTIVE_TYPES = /^(text\/html|application\/xhtml|image\/svg|application\/xml|text\/xml|text\/javascript|application\/javascript)/i;
const INLINE_TYPES = /^(image\/|audio\/|video\/|application\/pdf|text\/plain)/i;

function cleanMime(m: string | undefined, filename: string): string {
  const s = (m ?? '').toLowerCase().split(';')[0]!.trim();
  if (!s || s === 'application/octet-stream' || !/^[a-z0-9.+-]+\/[a-z0-9.+-]+$/.test(s)) return mimeFromName(filename);
  return s;
}

export function canReadUpload(ctx: Ctx, u: UserRow, up: UploadRow): boolean {
  if (u.role === 'admin' || up.user_id === u.id) return true;
  if (up.project_id && projectRole(ctx.db, u, up.project_id)) return true;
  return false;
}

export default (ctx: Ctx): FastifyPluginAsync =>
  async (app) => {
    const { db, cfg } = ctx;

    app.post('/api/uploads', async (req, reply) => {
      const u = requireUser(req);
      if (!req.isMultipart()) throw badRequest('Expected multipart/form-data');
      const created: UploadRow[] = [];
      let projectId: string | null = null;
      try {
        for await (const part of req.parts()) {
          if (part.type === 'field') {
            if (part.fieldname === 'projectId' && typeof part.value === 'string' && part.value) {
              requireProject(db, u, part.value, 'editor');
              projectId = part.value;
            }
            continue;
          }
          const id = crypto.randomUUID();
          const filename = sanitizeFilename(part.filename || 'file');
          const dir = path.join(cfg.uploadsDir, id);
          fs.mkdirSync(dir, { recursive: true });
          const dest = path.join(dir, filename === THUMB ? `_${filename}` : filename);
          try {
            await pipeline(part.file, fs.createWriteStream(dest, { flags: 'wx' }));
          } catch (err) {
            fs.rmSync(dir, { recursive: true, force: true });
            throw err;
          }
          if (part.file.truncated) {
            fs.rmSync(dir, { recursive: true, force: true });
            throw new HttpError(413, 'too_large', 'File exceeds the 50 MB limit');
          }
          const size = fs.statSync(dest).size;
          const mime = cleanMime(part.mimetype, filename);
          let hasThumb = 0;
          if (THUMBABLE.has(mime)) {
            try {
              await sharp(dest, { limitInputPixels: 100_000_000, animated: false })
                .rotate()
                .resize(320, 320, { fit: 'inside', withoutEnlargement: true })
                .webp({ quality: 78 })
                .toFile(path.join(dir, THUMB));
              hasThumb = 1;
            } catch (err) {
              ctx.log.warn({ err: (err as Error).message }, 'thumbnail failed');
            }
          }
          const row: UploadRow = { id, user_id: u.id, project_id: null, filename, mime, size, path: dest, has_thumb: hasThumb, created_at: now() };
          created.push(row);
        }
      } catch (err) {
        for (const r of created) fs.rmSync(path.dirname(r.path), { recursive: true, force: true });
        const e = err as { code?: string };
        if (e.code === 'FST_REQ_FILE_TOO_LARGE') throw new HttpError(413, 'too_large', 'File exceeds the 50 MB limit');
        throw err;
      }
      if (!created.length) throw badRequest('No file in upload', 'no_file');
      const ins = db.prepare(
        `INSERT INTO uploads(id, user_id, project_id, filename, mime, size, path, has_thumb, created_at) VALUES (?,?,?,?,?,?,?,?,?)`,
      );
      db.transaction(() => {
        for (const r of created) {
          r.project_id = projectId;
          ins.run(r.id, r.user_id, r.project_id, r.filename, r.mime, r.size, r.path, r.has_thumb, r.created_at);
        }
      })();
      ctx.audit(req, 'upload', created.map((r) => r.id).join(','), created.map((r) => ({ filename: r.filename, size: r.size, mime: r.mime })));
      reply.code(201);
      const dtos = created.map(attachmentDTO);
      return dtos.length === 1 ? dtos[0] : { ...dtos[0], files: dtos };
    });

    const loadUpload = (req: { params: unknown; user: UserRow | null }) => {
      const u = requireUser(req as never);
      const id = (req.params as { id: string }).id;
      if (!/^[0-9a-f-]{36}$/.test(id)) throw notFound('Upload not found');
      const up = db.prepare(`SELECT * FROM uploads WHERE id = ?`).get(id) as UploadRow | undefined;
      if (!up) throw notFound('Upload not found');
      if (!canReadUpload(ctx, u, up)) throw notFound('Upload not found');
      // defence in depth: stored path must live under UPLOADS_DIR/<id>/
      const real = fs.existsSync(up.path) ? fs.realpathSync(up.path) : '';
      if (!real || !real.startsWith(fs.realpathSync(path.join(cfg.uploadsDir, up.id)) + path.sep)) throw notFound('Upload file missing');
      return up;
    };

    app.get('/api/uploads/:id', async (req, reply) => {
      const up = loadUpload(req);
      const q = req.query as { download?: string };
      const active = ACTIVE_TYPES.test(up.mime);
      const inline = !active && INLINE_TYPES.test(up.mime) && q.download !== '1';
      reply.header('Content-Type', active ? 'application/octet-stream' : up.mime);
      reply.header('Content-Disposition', contentDisposition(inline ? 'inline' : 'attachment', up.filename));
      reply.header('Content-Security-Policy', "default-src 'none'; img-src 'self' data:; media-src 'self'; style-src 'unsafe-inline'; sandbox");
      reply.header('Cache-Control', 'private, max-age=86400');
      return reply.sendFile(path.basename(up.path), path.dirname(up.path), { contentType: false, cacheControl: false });
    });

    app.get('/api/uploads/:id/thumb', async (req, reply) => {
      const up = loadUpload(req);
      if (!up.has_thumb) throw notFound('No thumbnail');
      reply.header('Content-Type', 'image/webp');
      reply.header('Cache-Control', 'private, max-age=604800');
      return reply.sendFile(THUMB, path.dirname(up.path), { contentType: false, cacheControl: false });
    });

    app.delete('/api/uploads/:id', async (req) => {
      const u = requireUser(req);
      const up = db.prepare(`SELECT * FROM uploads WHERE id = ?`).get((req.params as { id: string }).id) as UploadRow | undefined;
      if (!up) throw notFound('Upload not found');
      if (up.user_id !== u.id && u.role !== 'admin') throw forbidden();
      const referenced = db.prepare(`SELECT 1 FROM messages WHERE attachments LIKE ? LIMIT 1`).get(`%"${up.id}"%`);
      if (referenced) return { ok: true, kept: true }; // referenced by chat history; keep
      db.prepare(`DELETE FROM uploads WHERE id = ?`).run(up.id);
      fs.rmSync(path.join(cfg.uploadsDir, up.id), { recursive: true, force: true });
      return { ok: true };
    });

    // ---- speech-to-text proxy ----
    app.post(
      '/api/transcribe',
      { config: { rateLimit: { max: 30, timeWindow: '1 minute', keyGenerator: (r) => r.user?.id ?? r.clientIp } } },
      async (req) => {
        requireUser(req);
        if (!req.isMultipart()) throw badRequest('Expected multipart/form-data');
        const file = await req.file({ limits: { fileSize: 25 * 1024 * 1024 } });
        if (!file) throw badRequest('Missing audio', 'no_file');
        const buf = await file.toBuffer();
        if (file.file.truncated) throw new HttpError(413, 'too_large', 'Audio too large');
        const form = new FormData();
        const type = cleanMime(file.mimetype, file.filename || 'audio.webm');
        form.append('audio', new Blob([new Uint8Array(buf)], { type }), sanitizeFilename(file.filename || 'audio.webm'));
        let res;
        try {
          res = await request(`${cfg.whisperUrl}/transcribe`, { method: 'POST', body: form, headersTimeout: 120_000, bodyTimeout: 120_000 });
        } catch (err) {
          throw new HttpError(502, 'whisper_unavailable', `Speech-to-text service unavailable: ${(err as Error).message}`);
        }
        const text = await res.body.text();
        if (res.statusCode >= 400) throw new HttpError(502, 'whisper_error', `Transcription failed (${res.statusCode})`);
        try {
          const j = JSON.parse(text) as { text?: string; language?: string; durationMs?: number };
          return { text: (j.text ?? '').trim(), language: j.language ?? null, durationMs: j.durationMs ?? null };
        } catch {
          throw new HttpError(502, 'whisper_error', 'Invalid response from speech-to-text service');
        }
      },
    );
  };

