import type { FastifyPluginAsync } from 'fastify';
import { z } from 'zod';
import { requireProject, requireUser, type ProjectRow } from '../auth.js';
import type { Ctx } from '../ctx.js';
import { HttpError } from '../lib/errors.js';

const startBody = z.object({ command: z.string().max(500).optional() }).optional();

export default (ctx: Ctx): FastifyPluginAsync =>
  async (app) => {
    const { db, cb } = ctx;
    const url = (p: ProjectRow) => `/preview/${p.slug}/`;

    async function status(p: ProjectRow) {
      try {
        const s = await cb.previewStatus(p.slug);
        return { running: !!s.running, port: s.port ?? p.preview_port, pid: s.pid ?? null, logTail: s.logTail ?? '', url: url(p) };
      } catch (err) {
        return { running: false, port: p.preview_port, pid: null, logTail: '', url: url(p), error: (err as Error).message };
      }
    }

    app.get('/api/projects/:id/preview/status', async (req) => {
      const u = requireUser(req);
      const { project } = requireProject(db, u, (req.params as { id: string }).id, 'viewer');
      return status(project);
    });

    app.post('/api/projects/:id/preview/start', async (req) => {
      const u = requireUser(req);
      const { project } = requireProject(db, u, (req.params as { id: string }).id, 'editor');
      const body = startBody.parse(req.body ?? {});
      try {
        await cb.previewStart(project.slug, project.preview_port, body?.command || project.preview_command);
      } catch (err) {
        throw new HttpError(502, 'preview_failed', (err as Error).message);
      }
      ctx.audit(req, 'preview_start', project.id);
      const s = await status(project);
      ctx.hub.broadcastProject(project.id, { t: 'preview_status', projectId: project.id, running: s.running, port: s.port });
      return s;
    });

    app.post('/api/projects/:id/preview/stop', async (req) => {
      const u = requireUser(req);
      const { project } = requireProject(db, u, (req.params as { id: string }).id, 'editor');
      try {
        await cb.previewStop(project.slug);
      } catch (err) {
        throw new HttpError(502, 'preview_failed', (err as Error).message);
      }
      ctx.audit(req, 'preview_stop', project.id);
      const s = await status(project);
      ctx.hub.broadcastProject(project.id, { t: 'preview_status', projectId: project.id, running: s.running, port: s.port });
      return s;
    });
  };

