import type { FastifyInstance, FastifyReply, FastifyRequest } from 'fastify';
import http from 'node:http';
import type { Duplex } from 'node:stream';
import { projectRole, SESSION_COOKIE, type ProjectRow, type UserRow } from '../auth.js';
import type { Ctx } from '../ctx.js';
import { normalizeIp } from '../lib/ip.js';

const HOP = new Set([
  'connection', 'keep-alive', 'proxy-authenticate', 'proxy-authorization', 'te', 'trailer', 'transfer-encoding', 'upgrade',
  'proxy-connection',
]);
const agent = new http.Agent({ keepAlive: true, maxSockets: 256 });

function parsePreviewUrl(url: string): { slug: string; rest: string } | null {
  const m = /^\/preview\/([a-z0-9][a-z0-9-]{0,47})(\/.*|\?.*)?$/.exec(url);
  if (!m) return null;
  return { slug: m[1]!, rest: m[2] ?? '' };
}

function upstreamPath(p: ProjectRow, url: string, rest: string): string {
  if (!p.preview_strip) return url;
  const r = rest.startsWith('/') ? rest : '/' + rest;
  return r;
}

/** Strip our session cookie before forwarding to user-controlled preview apps. */
function filterCookie(cookie: string | string[] | undefined): string | undefined {
  if (!cookie) return undefined;
  const s = Array.isArray(cookie) ? cookie.join('; ') : cookie;
  const kept = s
    .split(/;\s*/)
    .filter((c) => c && !c.startsWith(`${SESSION_COOKIE}=`));
  return kept.length ? kept.join('; ') : undefined;
}

function upstreamHeaders(ctx: Ctx, headers: http.IncomingHttpHeaders, port: number, clientIp: string, proto: string, upgrade: boolean) {
  const out: http.OutgoingHttpHeaders = {};
  for (const [k, v] of Object.entries(headers)) {
    if (v === undefined) continue;
    const lk = k.toLowerCase();
    if (!upgrade && HOP.has(lk)) continue;
    if (lk === 'cookie' || lk === 'host' || lk.startsWith('x-forwarded-')) continue;
    out[lk] = v;
  }
  const cookie = filterCookie(headers.cookie);
  if (cookie) out.cookie = cookie;
  // Dev servers (e.g. Vite) only accept localhost/IP Host headers by default.
  out.host = `localhost:${port}`;
  out['x-forwarded-for'] = clientIp;
  out['x-forwarded-host'] = String(headers['x-forwarded-host'] ?? headers.host ?? '');
  out['x-forwarded-proto'] = proto;
  return out;
}

function patchResponseHeaders(p: ProjectRow, port: number, headers: http.IncomingHttpHeaders, previewHost: string) {
  const out: Record<string, string | string[]> = {};
  for (const [k, v] of Object.entries(headers)) {
    if (v === undefined) continue;
    const lk = k.toLowerCase();
    if (HOP.has(lk) || lk === 'x-frame-options') continue;
    out[lk] = v;
  }
  const csp = out['content-security-policy'];
  if (typeof csp === 'string') {
    if (!/frame-ancestors/i.test(csp)) out['content-security-policy'] = `${csp}; frame-ancestors 'self'`;
  } else out['content-security-policy'] = "frame-ancestors 'self'";
  const loc = out['location'];
  if (typeof loc === 'string') {
    let l = loc.replace(new RegExp(`^https?://(localhost|127\\.0\\.0\\.1|0\\.0\\.0\\.0|${previewHost.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}):${port}`), '');
    if (p.preview_strip && l.startsWith('/') && !l.startsWith(`/preview/${p.slug}`)) l = `/preview/${p.slug}${l}`;
    out['location'] = l;
  }
  return out;
}

function previewErrorPage(title: string, msg: string, refresh: boolean) {
  return `<!doctype html><html><head><meta charset="utf-8">${refresh ? '<meta http-equiv="refresh" content="3">' : ''}<title>${title}</title>
<style>body{background:#07050a;color:#f6e9f0;font:14px/1.5 ui-monospace,monospace;display:grid;place-items:center;height:100vh;margin:0}
.b{border:1px solid #2a1626;background:#0f0a12;padding:24px 28px;border-radius:10px;max-width:520px}h1{color:#ff3e8a;font-size:16px;margin:0 0 8px}p{color:#a68a99;margin:0}</style>
</head><body><div class="b"><h1>${title}</h1><p>${msg}</p></div></body></html>`;
}

function authorize(ctx: Ctx, user: UserRow | null, slug: string): { project: ProjectRow } | { status: number; msg: string } {
  if (!user) return { status: 401, msg: 'Sign in to view this preview.' };
  const project = ctx.db.prepare(`SELECT * FROM projects WHERE slug = ?`).get(slug) as ProjectRow | undefined;
  if (!project || !projectRole(ctx.db, user, project.id)) return { status: 404, msg: 'Preview not found.' };
  return { project };
}

export function attachPreviewProxy(app: FastifyInstance, ctx: Ctx) {
  app.register(async (scope) => {
    // Pass request bodies through untouched.
    scope.removeAllContentTypeParsers();
    scope.addContentTypeParser('*', (_req, payload, done) => done(null, payload));

    const handler = async (req: FastifyRequest, reply: FastifyReply) => {
      const parsed = parsePreviewUrl(req.url);
      if (!parsed) return reply.code(404).type('text/html').send(previewErrorPage('Not found', 'Invalid preview URL.', false));
      const auth = authorize(ctx, req.user, parsed.slug);
      if ('status' in auth) return reply.code(auth.status).type('text/html').send(previewErrorPage(auth.status === 401 ? 'Sign in required' : 'Not found', auth.msg, false));
      const { project } = auth;
      if (!project.preview_strip && (parsed.rest === '' || parsed.rest.startsWith('?'))) {
        return reply.redirect(`/preview/${project.slug}/${parsed.rest}`, 302);
      }
      const port = project.preview_port;
      const proto = (req.headers['x-forwarded-proto'] as string | undefined) ?? req.protocol;
      const headers = upstreamHeaders(ctx, req.headers, port, req.clientIp, proto, false);
      const body = req.body as NodeJS.ReadableStream | undefined;

      return new Promise<void>((resolve) => {
        const up = http.request(
          { host: ctx.cfg.previewHost, port, method: req.method, path: upstreamPath(project, req.url, parsed.rest), headers, agent, timeout: 120_000 },
          (res) => {
            reply.code(res.statusCode ?? 502).headers(patchResponseHeaders(project, port, res.headers, ctx.cfg.previewHost));
            reply.send(res);
            resolve();
          },
        );
        up.on('timeout', () => up.destroy(new Error('upstream timeout')));
        up.on('error', (err) => {
          if (reply.sent) return resolve();
          const refused = (err as NodeJS.ErrnoException).code === 'ECONNREFUSED' || (err as NodeJS.ErrnoException).code === 'ENOTFOUND' || (err as NodeJS.ErrnoException).code === 'EAI_AGAIN';
          reply
            .code(502)
            .header('Cache-Control', 'no-store')
            .type('text/html')
            .send(
              previewErrorPage(
                refused ? 'Preview not running' : 'Preview error',
                refused ? `Nothing is listening on port ${port} yet. Start the preview or ask Claude to run the dev server — this page retries automatically.` : 'The preview server did not respond.',
                refused,
              ),
            );
          resolve();
        });
        if (body && typeof (body as NodeJS.ReadableStream).pipe === 'function' && req.method !== 'GET' && req.method !== 'HEAD') (body as NodeJS.ReadableStream).pipe(up);
        else up.end();
      });
    };
    scope.all('/preview/:slug', handler);
    scope.all('/preview/:slug/*', handler);
  });
}

/** Handle a WebSocket upgrade for /preview/<slug>/... (HMR). Returns true if handled. */
export function handlePreviewUpgrade(app: FastifyInstance, ctx: Ctx, req: http.IncomingMessage, socket: Duplex, head: Buffer): boolean {
  const url = req.url ?? '';
  const parsed = parsePreviewUrl(url);
  if (!parsed) return false;
  const reject = (code: number, text: string) => {
    socket.end(`HTTP/1.1 ${code} ${text}\r\nConnection: close\r\nContent-Length: 0\r\n\r\n`);
  };
  const clientIp = normalizeIp(clientIpOf(app, req));
  if (!ctx.ipRules.isAllowed(clientIp)) {
    reject(403, 'Forbidden');
    return true;
  }
  const cookies = app.parseCookie(req.headers.cookie ?? '');
  const user = ctx.sessions.lookup(cookies[SESSION_COOKIE]);
  const auth = authorize(ctx, user, parsed.slug);
  if ('status' in auth) {
    reject(auth.status, auth.status === 401 ? 'Unauthorized' : 'Not Found');
    return true;
  }
  const { project } = auth;
  const port = project.preview_port;
  const proto = (req.headers['x-forwarded-proto'] as string | undefined) ?? 'http';
  const headers = upstreamHeaders(ctx, req.headers, port, clientIp, proto, true);
  headers.connection = 'Upgrade';
  headers.upgrade = req.headers.upgrade ?? 'websocket';
  const up = http.request({ host: ctx.cfg.previewHost, port, method: req.method ?? 'GET', path: upstreamPath(project, url, parsed.rest), headers });
  up.on('upgrade', (res, upSocket, upHead) => {
    const lines = [`HTTP/1.1 ${res.statusCode} ${res.statusMessage}`];
    for (let i = 0; i < res.rawHeaders.length; i += 2) lines.push(`${res.rawHeaders[i]}: ${res.rawHeaders[i + 1]}`);
    socket.write(lines.join('\r\n') + '\r\n\r\n');
    if (upHead?.length) socket.write(upHead);
    if (head?.length) upSocket.write(head);
    upSocket.pipe(socket).pipe(upSocket);
    const kill = () => {
      upSocket.destroy();
      socket.destroy();
    };
    upSocket.on('error', kill);
    socket.on('error', kill);
    upSocket.on('close', kill);
    socket.on('close', kill);
  });
  up.on('response', (res) => {
    // upstream refused to upgrade: relay status
    reject(res.statusCode ?? 502, res.statusMessage ?? 'Bad Gateway');
    res.resume();
  });
  up.on('error', () => reject(502, 'Bad Gateway'));
  socket.on('error', () => up.destroy());
  up.end();
  return true;
}

/** Resolve the client IP for raw upgrade requests honouring TRUST_PROXY (mirrors Fastify's trustProxy). */
export function clientIpOf(app: FastifyInstance, req: http.IncomingMessage): string {
  const remote = normalizeIp(req.socket.remoteAddress ?? '');
  const xff = req.headers['x-forwarded-for'];
  if (!xff) return remote;
  const chain = (Array.isArray(xff) ? xff.join(',') : xff).split(',').map((s) => normalizeIp(s.trim())).filter(Boolean);
  // walk from the right while the hop is trusted
  let addr = remote;
  const trusted = (app as unknown as { __trust?: (ip: string) => boolean }).__trust;
  while (chain.length && trusted && trusted(addr)) addr = chain.pop()!;
  return addr;
}

