import type { FastifyInstance } from 'fastify';
import type http from 'node:http';
import type { Duplex } from 'node:stream';
import { WebSocketServer, type WebSocket } from 'ws';
import { projectRole, SESSION_COOKIE } from '../auth.js';
import type { Ctx } from '../ctx.js';
import { parseJson } from '../db.js';
import type { Client } from '../hub.js';
import type { ClientMsg, RunStatus, Suggestion } from '../shared/protocol.js';
import { clientIpOf, handlePreviewUpgrade } from './previewProxy.js';

export function attachWebSocket(app: FastifyInstance, ctx: Ctx) {
  const wss = new WebSocketServer({ noServer: true, maxPayload: 64 * 1024, perMessageDeflate: false });
  const { hub, db, runs } = ctx;

  const reject = (socket: Duplex, code: number, text: string) => {
    socket.end(`HTTP/1.1 ${code} ${text}\r\nConnection: close\r\nContent-Length: 0\r\n\r\n`);
  };

  app.server.on('upgrade', (req: http.IncomingMessage, socket: Duplex, head: Buffer) => {
    socket.on('error', () => socket.destroy());
    const url = req.url ?? '';
    if (url.startsWith('/preview/')) {
      handlePreviewUpgrade(app, ctx, req, socket, head);
      return;
    }
    if (url !== '/ws' && !url.startsWith('/ws?')) return reject(socket, 404, 'Not Found');
    const ip = clientIpOf(ctx, req);
    if (!ctx.ipRules.isAllowed(ip)) return reject(socket, 403, 'Forbidden');
    const origin = req.headers.origin;
    if (origin && !originOk(origin, req, ctx)) return reject(socket, 403, 'Forbidden');
    const token = app.parseCookie(req.headers.cookie ?? '')[SESSION_COOKIE];
    const user = ctx.sessions.lookup(token);
    if (!user) return reject(socket, 401, 'Unauthorized');
    wss.handleUpgrade(req, socket, head, (ws) => onConnection(ws, { id: user.id, role: user.role, email: user.email }, token!));
  });

  function onConnection(ws: WebSocket, user: Client['user'], token: string) {
    const c: Client = { ws, user, runs: new Set(), projects: new Set(), viewCache: new Map(), alive: true };
    hub.add(c);
    ws.on('pong', () => (c.alive = true));
    ws.on('close', () => hub.remove(c));
    ws.on('error', () => ws.terminate());
    ws.on('message', (raw, isBinary) => {
      if (isBinary) return;
      let msg: ClientMsg;
      try {
        msg = JSON.parse(raw.toString()) as ClientMsg;
      } catch {
        return hub.send(c, { t: 'error', message: 'invalid json' });
      }
      try {
        handle(c, msg);
      } catch (err) {
        ctx.log.warn({ err: (err as Error).message }, 'ws message failed');
        hub.send(c, { t: 'error', message: 'internal error' });
      }
    });
    // periodic session re-validation (logout / disable / password change)
    const recheck = setInterval(() => {
      const u = ctx.sessions.lookup(token);
      if (!u) ws.close(4401, 'session ended');
      else c.user = { id: u.id, role: u.role, email: u.email };
    }, 60_000);
    ws.on('close', () => clearInterval(recheck));
  }

  function handle(c: Client, msg: ClientMsg) {
    switch (msg?.t) {
      case 'ping':
        return hub.send(c, { t: 'pong' });
      case 'sub': {
        if (typeof msg.runId !== 'string') return;
        const run = db.prepare(`SELECT id, project_id, conversation_id, status FROM runs WHERE id = ?`).get(msg.runId) as
          | { id: string; project_id: string; conversation_id: string; status: RunStatus }
          | undefined;
        if (!run || !projectRole(db, c.user, run.project_id)) return hub.send(c, { t: 'error', message: `run ${msg.runId} not found` });
        const from = Number.isFinite(msg.fromSeq) ? Math.max(0, Math.floor(msg.fromSeq!)) : 0;
        // replay + subscribe synchronously: no events can slip in between
        const events = runs.replay(run.id, from);
        for (const e of events) hub.send(c, JSON.stringify({ t: 'run_event', runId: run.id, seq: e.seq, type: e.type, data: e.data }));
        hub.subRun(c, run.id);
        if (!runs.isActive(run.id)) {
          const fresh = db.prepare(`SELECT status FROM runs WHERE id = ?`).get(run.id) as { status: RunStatus };
          hub.send(c, { t: 'run_status', runId: run.id, conversationId: run.conversation_id, projectId: run.project_id, status: fresh.status });
          const m = db.prepare(`SELECT suggestions FROM messages WHERE run_id = ? AND role = 'assistant'`).get(run.id) as
            | { suggestions: string | null }
            | undefined;
          const items = parseJson<Suggestion[]>(m?.suggestions, []);
          if (items.length) hub.send(c, { t: 'suggestions', runId: run.id, items });
        } else {
          hub.send(c, { t: 'run_status', runId: run.id, conversationId: run.conversation_id, projectId: run.project_id, status: 'running' });
        }
        return;
      }
      case 'unsub':
        if (typeof msg.runId === 'string') hub.unsubRun(c, msg.runId);
        return;
      case 'sub_project': {
        if (typeof msg.projectId !== 'string') return;
        if (!projectRole(db, c.user, msg.projectId)) return hub.send(c, { t: 'error', message: `project ${msg.projectId} not found` });
        hub.subProject(c, msg.projectId);
        return;
      }
      case 'unsub_project':
        if (typeof msg.projectId === 'string') hub.unsubProject(c, msg.projectId);
        return;
      default:
        hub.send(c, { t: 'error', message: 'unknown message' });
    }
  }

  const heartbeat = setInterval(() => {
    for (const c of hub.clients) {
      if (!c.alive) {
        c.ws.terminate();
        continue;
      }
      c.alive = false;
      try {
        c.ws.ping();
      } catch {
        /* closed */
      }
    }
  }, 30_000);
  heartbeat.unref();
  app.addHook('onClose', async () => {
    clearInterval(heartbeat);
    wss.close();
  });
}

function originOk(origin: string, req: http.IncomingMessage, ctx: Ctx): boolean {
  try {
    const o = new URL(origin);
    if (o.origin === new URL(ctx.cfg.publicUrl).origin) return true;
    const host = (req.headers['x-forwarded-host'] as string | undefined) ?? req.headers.host;
    return !!host && o.host === host;
  } catch {
    return false;
  }
}

