        hub.send(c, { t: 'error', message: 'unknown message' });
    }
  }

  const heartbeat = setInterval(() => {
    for (const c of hub.clients) {
      if (!c.alive) {
        c.ws.terminate();
        continue;
      }
      c.alive = false;
      try {
        c.ws.ping();
      } catch {
        /* closed */
      }
    }
  }, 30_000);
  heartbeat.unref();
  app.addHook('onClose', async () => {
    clearInterval(heartbeat);
    wss.close();
  });
}

function originOk(origin: string, req: http.IncomingMessage, ctx: Ctx): boolean {
  try {
    const o = new URL(origin);
    if (o.origin === new URL(ctx.cfg.publicUrl).origin) return true;
    const host = (req.headers['x-forwarded-host'] as string | undefined) ?? req.headers.host;
    return !!host && o.host === host;
  } catch {
    return false;
  }
}

