import type { FastifyPluginAsync, FastifyReply, FastifyRequest } from 'fastify';
import fs from 'node:fs';
import path from 'node:path';
import type { Ctx } from '../ctx.js';

/** Serves the built SPA from WEB_DIST with history fallback; hashed assets get long-lived caching. */
export default (ctx: Ctx): FastifyPluginAsync =>
  async (app) => {
    const root = ctx.cfg.webDist;

    const notFoundApi = (reply: FastifyReply) => reply.code(404).send({ error: { code: 'not_found', message: 'Not found' } });

    const handler = async (req: FastifyRequest, reply: FastifyReply) => {
      const urlPath = decodeSafe(req.url.split('?')[0]!);
      if (urlPath === null) return reply.code(400).send('Bad request');
      if (urlPath.startsWith('/api/') || urlPath === '/api' || urlPath === '/ws') return notFoundApi(reply);
      const index = path.join(root, 'index.html');
      if (!fs.existsSync(index)) {
        return reply.code(503).type('text/plain').send('Web UI not built (WEB_DIST missing index.html)');
      }
      const rel = path.posix.normalize(urlPath).replace(/^\/+/, '');
      if (rel && !rel.startsWith('..')) {
        const abs = path.join(root, rel);
        if (abs.startsWith(root + path.sep)) {
          let st: fs.Stats | null = null;
          try {
            st = fs.statSync(abs);
          } catch {
            st = null;
          }
          if (st?.isFile()) {
            const hashed = rel.startsWith('assets/') || /[.-][A-Za-z0-9_-]{8,}\.(js|css|woff2?|ttf|svg|png|jpe?g|webp|wasm)$/.test(rel);
            reply.header('Cache-Control', hashed ? 'public, max-age=31536000, immutable' : 'public, max-age=300');
            return reply.sendFile(rel, root, { cacheControl: false });
          }
          // Missing asset files must 404 (not return index.html with a JS MIME expectation).
          if (rel.startsWith('assets/') || /\.[a-z0-9]{1,5}$/i.test(rel)) return reply.code(404).type('text/plain').send('Not found');
        }
      }
      reply.header('Cache-Control', 'no-cache');
      return reply.sendFile('index.html', root, { cacheControl: false });
    };

    app.get('/', handler);
    app.get('/*', handler);
    app.setNotFoundHandler((req, reply) => {
      if (req.url.startsWith('/api')) return notFoundApi(reply);
      return reply.code(404).type('text/plain').send('Not found');
    });
  };

function decodeSafe(s: string): string | null {
  try {
    const d = decodeURIComponent(s);
    return d.includes('\0') ? null : d;
  } catch {
    return null;
  }
}

