import type { FastifyPluginAsync } from 'fastify';
import { requireUser } from '../auth.js';
import type { Ctx } from '../ctx.js';
import { effectiveDailyLimit, startOfTodayUtc } from './conversations.js';

export default (ctx: Ctx): FastifyPluginAsync =>
  async (app) => {
    const { db, settings } = ctx;

    const window = (userId: string, since: number) => {
      const r = db
        .prepare(
          `SELECT COALESCE(SUM(input_tokens),0) AS i, COALESCE(SUM(output_tokens),0) AS o, COALESCE(SUM(cache_read),0) AS cr,
                  COALESCE(SUM(cache_write),0) AS cw, COUNT(*) AS n, COALESCE(SUM(cost_usd),0) AS c
           FROM runs WHERE user_id = ? AND started_at >= ?`,
        )
        .get(userId, since) as { i: number; o: number; cr: number; cw: number; n: number; c: number };
      return { inputTokens: r.i, outputTokens: r.o, cacheReadTokens: r.cr, cacheWriteTokens: r.cw, runs: r.n, costUsd: Math.round(r.c * 1e6) / 1e6 };
    };

    app.get('/api/usage/me', async (req) => {
      const u = requireUser(req);
      ctx.runs.flushAll();
      const today = startOfTodayUtc();
      const d30 = Date.now() - 30 * 86400_000;
      const byModel = db
        .prepare(
          `SELECT model, COALESCE(SUM(input_tokens + output_tokens),0) AS tokens, COUNT(*) AS runs FROM runs
           WHERE user_id = ? AND started_at >= ? GROUP BY model ORDER BY tokens DESC`,
        )
        .all(u.id, d30) as { model: string; tokens: number; runs: number }[];
      const s = settings.get();
      return {
        today: window(u.id, today),
        d7: window(u.id, Date.now() - 7 * 86400_000),
        d30: window(u.id, d30),
        byModel,
        limits: { dailyTokens: effectiveDailyLimit(ctx, u), globalDailyTokens: s.globalDailyTokens },
        resetsAt: new Date(today + 86400_000).toISOString(),
      };
    });

    app.get('/api/models', async (req) => {
      const u = requireUser(req);
      const s = settings.get();
      const allowed = u.allowed_models ? (JSON.parse(u.allowed_models) as string[]) : null;
      const list = allowed && allowed.length ? s.models.filter((m) => allowed.includes(m.id)) : s.models;
      return list.map((m) => ({ ...m, ...(m.id === s.defaultModel ? { default: true } : {}) }));
    });
  };

