import type { FastifyPluginAsync } from 'fastify';
import crypto from 'node:crypto';
import { z } from 'zod';
import { hashPassword, requireAdmin, userDTO, type UserRow } from '../auth.js';
import type { Ctx } from '../ctx.js';
import { iso, now, parseJson } from '../db.js';
import { loadAttachments } from '../dto.js';
import { IpRules, type IpRuleRow } from '../iprules.js';
import { badRequest, conflict, HttpError, notFound } from '../lib/errors.js';
import { parseCidr } from '../lib/ip.js';
import { startOfTodayUtc } from './conversations.js';

const MODES = ['auto', 'edit', 'plan', 'ask'] as const;
const limitsSchema = z
  .object({
    dailyTokens: z.number().int().min(0).nullable().optional(),
    models: z.array(z.string().max(100)).max(50).nullable().optional(),
    modes: z.array(z.enum(MODES)).max(4).nullable().optional(),
  })
  .optional();
const createUserSchema = z.object({
  email: z.string().trim().toLowerCase().email().max(320),
  name: z.string().trim().min(1).max(100),
  password: z.string().min(8).max(1000),
  role: z.enum(['admin', 'member']).default('member'),
  disabled: z.boolean().optional(),
  limits: limitsSchema,
});
const patchUserSchema = z.object({
  email: z.string().trim().toLowerCase().email().max(320).optional(),
  name: z.string().trim().min(1).max(100).optional(),
  password: z.string().min(8).max(1000).optional(),
  role: z.enum(['admin', 'member']).optional(),
  disabled: z.boolean().optional(),
  limits: limitsSchema,
  unlock: z.boolean().optional(),
});
const grantsSchema = z.object({
  grants: z.array(z.object({ projectId: z.string(), role: z.enum(['owner', 'editor', 'viewer']) })).max(1000),
});
const ipRuleSchema = z.object({ kind: z.enum(['allow', 'block']), cidr: z.string().trim().max(64), note: z.string().max(200).optional() });
const settingsSchema = z.object({
  models: z.array(z.object({ id: z.string().trim().min(1).max(100).regex(/^[A-Za-z0-9._:\-[\]]+$/), label: z.string().trim().min(1).max(60) })).min(1).max(30).optional(),
  defaultModel: z.string().max(100).optional(),
  globalDailyTokens: z.number().int().min(0).nullable().optional(),
  defaultUserDailyTokens: z.number().int().min(0).nullable().optional(),
  maxTurns: z.number().int().min(1).max(500).optional(),
  claudeAuthToken: z.string().max(4000).nullable().optional(),
});

const RANGES: Record<string, { span: number; bucket: number }> = {
  '1h': { span: 3600_000, bucket: 60_000 },
  '24h': { span: 86400_000, bucket: 3600_000 },
  '7d': { span: 7 * 86400_000, bucket: 6 * 3600_000 },
  '30d': { span: 30 * 86400_000, bucket: 86400_000 },
};

function encCursor(ts: number, id: string | number) {
  return Buffer.from(`${ts}:${id}`).toString('base64url');
}
function decCursor(c: string | undefined): { ts: number; id: string } | null {
  if (!c) return null;
  try {
    const s = Buffer.from(c, 'base64url').toString();
    const i = s.indexOf(':');
    const ts = Number(s.slice(0, i));
    if (!Number.isFinite(ts)) return null;
    return { ts, id: s.slice(i + 1) };
  } catch {
    return null;
  }
}

function normalizePath(p: string): string {
  return p
    .replace(/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/gi, ':id')
    .replace(/^\/preview\/[^/]+\/.*/, '/preview/:slug/*')
    .replace(/^\/assets\/.*/, '/assets/*');
}

export default (ctx: Ctx): FastifyPluginAsync =>
  async (app) => {
    const { db, settings, ipRules } = ctx;
    app.addHook('onRequest', async (req) => {
      if (req.url.startsWith('/api/admin')) requireAdmin(req);
    });

    // ---------- overview ----------
    app.get('/api/admin/overview', async () => {
      ctx.runs.flushAll();
      const today = startOfTodayUtc();
      const t = now();
      const r = db
        .prepare(
          `SELECT COUNT(*) AS runs, COALESCE(SUM(input_tokens + output_tokens),0) AS tokens, COALESCE(SUM(cost_usd),0) AS cost,
                  SUM(CASE WHEN status = 'error' THEN 1 ELSE 0 END) AS errors,
                  SUM(CASE WHEN status IN ('done','error') THEN 1 ELSE 0 END) AS finished,
                  COUNT(DISTINCT user_id) AS users
           FROM runs WHERE started_at >= ?`,
        )
        .get(today) as { runs: number; tokens: number; cost: number; errors: number; finished: number; users: number };
      const activeUsers = (db.prepare(`SELECT COUNT(DISTINCT user_id) AS n FROM sessions WHERE last_seen_at >= ?`).get(t - 15 * 60_000) as { n: number }).n;
      const users24h = (db.prepare(`SELECT COUNT(*) AS n FROM users WHERE last_seen_at >= ?`).get(t - 86400_000) as { n: number }).n;
      const reqs = (db.prepare(`SELECT COUNT(*) AS n FROM request_log WHERE ts >= ?`).get(t - 5 * 60_000) as { n: number }).n;
      const activeRuns = (db.prepare(`SELECT COUNT(*) AS n FROM runs WHERE status IN ('queued','running')`).get() as { n: number }).n;
      const totals = db.prepare(`SELECT (SELECT COUNT(*) FROM users) AS users, (SELECT COUNT(*) FROM projects WHERE archived = 0) AS projects`).get() as {
        users: number; projects: number;
      };
      const loginFailures = (db.prepare(`SELECT COUNT(*) AS n FROM audit_log WHERE action = 'login_failed' AND ts >= ?`).get(t - 86400_000) as { n: number }).n;
      let claudebox: Record<string, unknown> = { ok: false };
      try {
        claudebox = { ok: true, ...(await Promise.race([ctx.cb.health(), new Promise<never>((_, rej) => setTimeout(() => rej(new Error('timeout')), 2000))])) };
      } catch (err) {
        claudebox = { ok: false, error: (err as Error).message };
      }
      return {
        activeUsers,
        users24h,
        usersWithRunsToday: r.users,
        runsToday: r.runs,
        tokensToday: r.tokens,
        costToday: Math.round(r.cost * 1e4) / 1e4,
        errorRate: r.finished ? r.errors / r.finished : 0,
        activeRuns,
        reqPerMin: Math.round((reqs / 5) * 10) / 10,
        totalUsers: totals.users,
        totalProjects: totals.projects,
        loginFailures24h: loginFailures,
        claudebox,
      };
    });

    // ---------- timeseries ----------
    app.get('/api/admin/timeseries', async (req) => {
      ctx.runs.flushAll();
      const q = req.query as { metric?: string; range?: string; groupBy?: string };
      const metric = (['tokens', 'runs', 'requests', 'cost'] as const).find((m) => m === q.metric) ?? 'tokens';
      const range = RANGES[q.range ?? '24h'] ? (q.range ?? '24h') : '24h';
      const { span, bucket } = RANGES[range]!;
      let groupBy = (['user', 'project', 'model'] as const).find((g) => g === q.groupBy) ?? null;
      if (metric === 'requests' && groupBy !== 'user') groupBy = null;
      const end = Math.ceil(now() / bucket) * bucket;
      const start = end - span;
      let rows: { b: number; k: string | null; v: number }[];
      if (metric === 'requests') {
        rows = db
          .prepare(
            `SELECT CAST((ts - ?) / ? AS INTEGER) AS b, ${groupBy ? 'user_id' : 'NULL'} AS k, COUNT(*) AS v FROM request_log WHERE ts >= ? GROUP BY b, k`,
          )
          .all(start, bucket, start) as typeof rows;
      } else {
        const agg = metric === 'tokens' ? 'SUM(input_tokens + output_tokens)' : metric === 'runs' ? 'COUNT(*)' : 'SUM(cost_usd)';
        const col = groupBy === 'user' ? 'user_id' : groupBy === 'project' ? 'project_id' : groupBy === 'model' ? 'model' : 'NULL';
        rows = db
          .prepare(`SELECT CAST((started_at - ?) / ? AS INTEGER) AS b, ${col} AS k, ${agg} AS v FROM runs WHERE started_at >= ? GROUP BY b, k`)
          .all(start, bucket, start) as typeof rows;
      }
      // top 8 keys, rest → "other"
      const totals = new Map<string, number>();
      for (const r of rows) totals.set(r.k ?? '_', (totals.get(r.k ?? '_') ?? 0) + (r.v ?? 0));
      const top = [...totals.entries()].sort((a, b) => b[1] - a[1]).slice(0, 8).map(([k]) => k);
      const topSet = new Set(top);
      const labels = new Map<string, string>();
      if (groupBy === 'user')
        for (const k of top) labels.set(k, (db.prepare(`SELECT name FROM users WHERE id = ?`).get(k) as { name: string } | undefined)?.name ?? 'anonymous');
      else if (groupBy === 'project')
        for (const k of top) labels.set(k, (db.prepare(`SELECT name FROM projects WHERE id = ?`).get(k) as { name: string } | undefined)?.name ?? 'deleted');
      else for (const k of top) labels.set(k, k);
      const n = Math.round(span / bucket);
      const points: Record<string, number | string>[] = [];
      for (let i = 0; i < n; i++) points.push({ t: new Date(start + i * bucket).toISOString(), total: 0 });
      let hasOther = false;
      for (const r of rows) {
        const p = points[r.b];
        if (!p) continue;
        const v = r.v ?? 0;
        p.total = (p.total as number) + v;
        if (groupBy) {
          const key = topSet.has(r.k ?? '_') ? (r.k ?? '_') : 'other';
          if (key === 'other') hasOther = true;
          p[key] = ((p[key] as number | undefined) ?? 0) + v;
        }
      }
      if (metric === 'cost') for (const p of points) for (const k of Object.keys(p)) if (typeof p[k] === 'number') p[k] = Math.round((p[k] as number) * 1e4) / 1e4;
      const keys = groupBy ? [...top.map((k) => ({ key: k, label: labels.get(k) ?? k })), ...(hasOther ? [{ key: 'other', label: 'Other' }] : [])] : [];
      return { metric, range, groupBy, bucketMs: bucket, start: new Date(start).toISOString(), keys, points };
    });

    // ---------- users ----------
    const userWithStats = (u: UserRow) => {
      const today = startOfTodayUtc();
      const s = db
        .prepare(`SELECT COALESCE(SUM(input_tokens + output_tokens),0) AS tokens, COUNT(*) AS runs FROM runs WHERE user_id = ? AND started_at >= ?`)
        .get(u.id, today) as { tokens: number; runs: number };
      const p = db.prepare(`SELECT COUNT(*) AS n FROM project_members WHERE user_id = ?`).get(u.id) as { n: number };
      return { ...userDTO(u), tokensToday: s.tokens, runsToday: s.runs, projectCount: p.n, locked: !!(u.locked_until && u.locked_until > now()) };
    };

    app.get('/api/admin/users', async () => {
      return (db.prepare(`SELECT * FROM users ORDER BY created_at`).all() as UserRow[]).map(userWithStats);
    });

    app.post('/api/admin/users', async (req, reply) => {
      const body = createUserSchema.parse(req.body);
      if (db.prepare(`SELECT 1 FROM users WHERE email = ?`).get(body.email)) throw conflict('A user with this email already exists', 'email_taken');
      const id = crypto.randomUUID();
      db.prepare(
        `INSERT INTO users(id, email, name, password_hash, role, disabled, daily_tokens, allowed_models, allowed_modes, created_at) VALUES (?,?,?,?,?,?,?,?,?,?)`,
      ).run(
        id, body.email, body.name, await hashPassword(body.password), body.role, body.disabled ? 1 : 0,
        body.limits?.dailyTokens ?? null,
        body.limits?.models ? JSON.stringify(body.limits.models) : null,
        body.limits?.modes ? JSON.stringify(body.limits.modes) : null,
        now(),
      );
      ctx.audit(req, 'user_create', id, { email: body.email, role: body.role });
      reply.code(201);
      return userWithStats(db.prepare(`SELECT * FROM users WHERE id = ?`).get(id) as UserRow);
    });

    app.get('/api/admin/users/:id', async (req) => {
      const u = db.prepare(`SELECT * FROM users WHERE id = ?`).get((req.params as { id: string }).id) as UserRow | undefined;
      if (!u) throw notFound('User not found');
      return userWithStats(u);
    });

    app.patch('/api/admin/users/:id', async (req) => {
      const me = req.user!;
      const id = (req.params as { id: string }).id;
      const u = db.prepare(`SELECT * FROM users WHERE id = ?`).get(id) as UserRow | undefined;
      if (!u) throw notFound('User not found');
      const body = patchUserSchema.parse(req.body);
      if (id === me.id && (body.disabled === true || body.role === 'member')) throw badRequest('You cannot disable or demote yourself', 'self_modify');
      if (body.email && body.email !== u.email && db.prepare(`SELECT 1 FROM users WHERE email = ?`).get(body.email))
        throw conflict('A user with this email already exists', 'email_taken');
      const sets: string[] = [];
      const vals: unknown[] = [];
      const add = (c: string, v: unknown) => {
        sets.push(`${c} = ?`);
        vals.push(v);
      };
      if (body.email !== undefined) add('email', body.email);
      if (body.name !== undefined) add('name', body.name);
      if (body.role !== undefined) add('role', body.role);
      if (body.disabled !== undefined) add('disabled', body.disabled ? 1 : 0);
      if (body.password !== undefined) add('password_hash', await hashPassword(body.password));
      if (body.unlock) {
        add('failed_logins', 0);
        add('locked_until', null);
      }
      if (body.limits) {
        if (body.limits.dailyTokens !== undefined) add('daily_tokens', body.limits.dailyTokens);
        if (body.limits.models !== undefined) add('allowed_models', body.limits.models ? JSON.stringify(body.limits.models) : null);
        if (body.limits.modes !== undefined) add('allowed_modes', body.limits.modes ? JSON.stringify(body.limits.modes) : null);
      }
      if (sets.length) db.prepare(`UPDATE users SET ${sets.join(', ')} WHERE id = ?`).run(...vals, id);
      if (body.disabled === true || body.password !== undefined) {
        ctx.sessions.destroyAllForUser(id);
        ctx.hub.kickUser(id);
      }
      if (body.role !== undefined) ctx.hub.invalidatePermissions();
      ctx.audit(req, 'user_update', id, { ...body, password: body.password ? '[changed]' : undefined });
      return userWithStats(db.prepare(`SELECT * FROM users WHERE id = ?`).get(id) as UserRow);
    });

    app.delete('/api/admin/users/:id', async (req) => {
      const id = (req.params as { id: string }).id;
      if (id === req.user!.id) throw badRequest('You cannot delete yourself', 'self_modify');
      const u = db.prepare(`SELECT * FROM users WHERE id = ?`).get(id) as UserRow | undefined;
      if (!u) throw notFound('User not found');
      ctx.hub.kickUser(id);
      db.prepare(`DELETE FROM users WHERE id = ?`).run(id); // sessions + memberships cascade; runs/messages keep user_id for history
      ctx.audit(req, 'user_delete', id, { email: u.email });
      return { ok: true };
    });

    app.get('/api/admin/users/:id/projects', async (req) => {
      const id = (req.params as { id: string }).id;
      if (!db.prepare(`SELECT 1 FROM users WHERE id = ?`).get(id)) throw notFound('User not found');
      return db
        .prepare(
          `SELECT p.id AS projectId, p.name, p.slug, p.color, p.icon, m.role FROM project_members m JOIN projects p ON p.id = m.project_id
           WHERE m.user_id = ? ORDER BY p.name`,
        )
        .all(id);
    });

    app.put('/api/admin/users/:id/projects', async (req) => {
      const id = (req.params as { id: string }).id;
      if (!db.prepare(`SELECT 1 FROM users WHERE id = ?`).get(id)) throw notFound('User not found');
      const { grants } = grantsSchema.parse(req.body);
      for (const g of grants) if (!db.prepare(`SELECT 1 FROM projects WHERE id = ?`).get(g.projectId)) throw badRequest(`Unknown project ${g.projectId}`);
      const t = now();
      db.transaction(() => {
        db.prepare(`DELETE FROM project_members WHERE user_id = ?`).run(id);
        const ins = db.prepare(`INSERT INTO project_members(project_id, user_id, role, created_at) VALUES (?,?,?,?)`);
        for (const g of grants) ins.run(g.projectId, id, g.role, t);
      })();
      ctx.hub.invalidatePermissions();
      ctx.audit(req, 'user_grants', id, grants);
      return db
        .prepare(
          `SELECT p.id AS projectId, p.name, p.slug, p.color, p.icon, m.role FROM project_members m JOIN projects p ON p.id = m.project_id WHERE m.user_id = ? ORDER BY p.name`,
        )
        .all(id);
    });

    // ---------- prompts log ----------
    app.get('/api/admin/prompts', async (req) => {
      const q = req.query as { userId?: string; projectId?: string; q?: string; cursor?: string; limit?: string };
      const limit = Math.min(200, Math.max(1, Number(q.limit) || 50));
      const where: string[] = [`m.role = 'user'`];
      const vals: unknown[] = [];
      if (q.userId) {
        where.push('m.user_id = ?');
        vals.push(q.userId);
      }
      if (q.projectId) {
        where.push('c.project_id = ?');
        vals.push(q.projectId);
      }
      if (q.q) {
        where.push(`m.content LIKE ? ESCAPE '\\'`);
        vals.push(`%${q.q.replace(/[\\%_]/g, (c) => '\\' + c)}%`);
      }
      const cur = decCursor(q.cursor);
      if (cur) {
        where.push('(m.created_at < ? OR (m.created_at = ? AND m.id < ?))');
        vals.push(cur.ts, cur.ts, cur.id);
      }
      const rows = db
        .prepare(
          `SELECT m.id, m.content, m.attachments, m.created_at, m.run_id, m.conversation_id, m.user_id,
                  c.title AS conv_title, c.project_id, p.name AS project_name, p.slug AS project_slug,
                  u.name AS user_name, u.email AS user_email,
                  r.model, r.mode, r.thinking, r.status, r.input_tokens, r.output_tokens, r.cost_usd, r.duration_ms, r.ip
           FROM messages m JOIN conversations c ON c.id = m.conversation_id
           LEFT JOIN projects p ON p.id = c.project_id LEFT JOIN users u ON u.id = m.user_id LEFT JOIN runs r ON r.id = m.run_id
           WHERE ${where.join(' AND ')} ORDER BY m.created_at DESC, m.id DESC LIMIT ?`,
        )
        .all(...vals, limit + 1) as Record<string, unknown>[];
      const more = rows.length > limit;
      const page = rows.slice(0, limit);
      const items = page.map((r) => ({
        id: r.id,
        text: r.content,
        attachments: loadAttachments(db, parseJson<string[]>(r.attachments as string, [])),
        createdAt: iso(r.created_at as number),
        runId: r.run_id,
        conversationId: r.conversation_id,
        conversationTitle: r.conv_title,
        projectId: r.project_id,
        projectName: r.project_name,
        projectSlug: r.project_slug,
        userId: r.user_id,
        userName: r.user_name,
        userEmail: r.user_email,
        model: r.model,
        mode: r.mode,
        thinking: r.thinking,
        status: r.status,
        inputTokens: r.input_tokens ?? 0,
        outputTokens: r.output_tokens ?? 0,
        costUsd: r.cost_usd ?? 0,
        durationMs: r.duration_ms,
        ip: r.ip,
      }));
      const last = page[page.length - 1];
      return { items, nextCursor: more && last ? encCursor(last.created_at as number, last.id as string) : null };
    });

    // ---------- activity (audit log) ----------
    app.get('/api/admin/activity', async (req) => {
      const q = req.query as { cursor?: string; action?: string; userId?: string; limit?: string };
      const limit = Math.min(500, Math.max(1, Number(q.limit) || 100));
      const where: string[] = ['1=1'];
      const vals: unknown[] = [];
      if (q.action) {
        where.push('a.action = ?');
        vals.push(q.action);
      }
      if (q.userId) {
        where.push('a.user_id = ?');
        vals.push(q.userId);
      }
      if (q.cursor && /^\d+$/.test(q.cursor)) {
        where.push('a.id < ?');
        vals.push(Number(q.cursor));
      }
      const rows = db
        .prepare(
          `SELECT a.*, u.name AS user_name, u.email AS user_email FROM audit_log a LEFT JOIN users u ON u.id = a.user_id
           WHERE ${where.join(' AND ')} ORDER BY a.id DESC LIMIT ?`,
        )
        .all(...vals, limit + 1) as {
        id: number; user_id: string | null; ip: string | null; action: string; target: string | null; meta: string | null; ts: number;
        user_name: string | null; user_email: string | null;
      }[];
      const more = rows.length > limit;
      const page = rows.slice(0, limit);
      return {
        items: page.map((r) => ({
          id: r.id, userId: r.user_id, userName: r.user_name, userEmail: r.user_email, ip: r.ip, action: r.action, target: r.target,
          meta: parseJson(r.meta, null), ts: iso(r.ts),
        })),
        nextCursor: more ? String(page[page.length - 1]!.id) : null,
      };
    });

    // ---------- traffic ----------
    app.get('/api/admin/traffic', async (req) => {
      const q = req.query as { range?: string };
      const range = RANGES[q.range ?? '24h'] ? (q.range ?? '24h') : '24h';
      const since = now() - RANGES[range]!.span;
      const totals = db
        .prepare(
          `SELECT COUNT(*) AS requests, COUNT(DISTINCT ip) AS uniqueIps, SUM(CASE WHEN status >= 500 THEN 1 ELSE 0 END) AS serverErrors,
                  SUM(CASE WHEN status >= 400 AND status < 500 THEN 1 ELSE 0 END) AS clientErrors, AVG(ms) AS avgMs
           FROM request_log WHERE ts >= ?`,
        )
        .get(since) as Record<string, number | null>;
      const topIps = (
        db
          .prepare(
            `SELECT ip, COUNT(*) AS count, MAX(ts) AS last, SUM(CASE WHEN status >= 400 THEN 1 ELSE 0 END) AS errors,
                    COUNT(DISTINCT user_id) AS users
             FROM request_log WHERE ts >= ? GROUP BY ip ORDER BY count DESC LIMIT 50`,
          )
          .all(since) as { ip: string; count: number; last: number; errors: number; users: number }[]
      ).map((r) => ({ ip: r.ip, count: r.count, errors: r.errors, users: r.users, lastSeen: iso(r.last), blocked: !ipRules.isAllowed(r.ip) }));
      const byStatus = db.prepare(`SELECT status, COUNT(*) AS count FROM request_log WHERE ts >= ? GROUP BY status ORDER BY count DESC`).all(since);
      const pathRows = db
        .prepare(`SELECT path, COUNT(*) AS count, SUM(ms) AS ms FROM request_log WHERE ts >= ? GROUP BY path ORDER BY count DESC LIMIT 3000`)
        .all(since) as { path: string; count: number; ms: number }[];
      const agg = new Map<string, { count: number; ms: number }>();
      for (const r of pathRows) {
        const k = normalizePath(r.path);
        const a = agg.get(k) ?? { count: 0, ms: 0 };
        a.count += r.count;
        a.ms += r.ms;
        agg.set(k, a);
      }
      const topPaths = [...agg.entries()]
        .sort((a, b) => b[1].count - a[1].count)
        .slice(0, 50)
        .map(([path, a]) => ({ path, count: a.count, avgMs: Math.round((a.ms / a.count) * 10) / 10 }));
      const recent = (
        db
          .prepare(
            `SELECT l.ts, l.ip, l.user_id, l.method, l.path, l.status, l.ms, u.name AS user_name FROM request_log l
             LEFT JOIN users u ON u.id = l.user_id ORDER BY l.ts DESC LIMIT 100`,
          )
          .all() as { ts: number; ip: string; user_id: string | null; method: string; path: string; status: number; ms: number; user_name: string | null }[]
      ).map((r) => ({ ts: iso(r.ts), ip: r.ip, userId: r.user_id, userName: r.user_name, method: r.method, path: r.path, status: r.status, ms: r.ms }));
      const loginFailures = (
        db
          .prepare(`SELECT id, ip, action, target, meta, ts FROM audit_log WHERE action IN ('login_failed','account_locked') AND ts >= ? ORDER BY id DESC LIMIT 100`)
          .all(since) as { id: number; ip: string; action: string; target: string; meta: string | null; ts: number }[]
      ).map((r) => ({ id: r.id, ip: r.ip, action: r.action, email: r.target, meta: parseJson(r.meta, null), ts: iso(r.ts) }));
      return {
        range,
        totals: { ...totals, avgMs: totals.avgMs ? Math.round(totals.avgMs * 10) / 10 : 0 },
        topIps, byStatus, topPaths, recent, loginFailures,
      };
    });

    // ---------- IP rules ----------
    const ruleDTO = (r: IpRuleRow) => ({ id: r.id, kind: r.kind, cidr: r.cidr, note: r.note, createdBy: r.created_by, createdAt: iso(r.created_at) });
    app.get('/api/admin/ip-rules', async (req) => ({ rules: ipRules.list().map(ruleDTO), yourIp: req.clientIp }));

    app.post('/api/admin/ip-rules', async (req, reply) => {
      const body = ipRuleSchema.parse(req.body);
      const parsed = parseCidr(body.cidr);
      if (!parsed) throw badRequest('Invalid IP or CIDR', 'invalid_cidr');
      const cidr = `${parsed.address}/${parsed.prefix}`;
      const myIp = req.clientIp;
      const current = ipRules.list();
      const next = [...current, { kind: body.kind, cidr }];
      let warning: string | null = null;
      const extra: { kind: 'allow'; cidr: string; note: string }[] = [];
      if (!IpRules.wouldAllow(next, myIp)) {
        if (body.kind === 'block') throw new HttpError(400, 'self_lockout', `This rule would block your own IP (${myIp}). Not saved.`);
        const mine = parseCidr(myIp);
        if (!mine) throw new HttpError(400, 'self_lockout', 'Cannot determine your IP; refusing to add an allowlist rule that may lock you out.');
        extra.push({ kind: 'allow', cidr: `${mine.address}/${mine.prefix}`, note: 'auto-added: admin IP (lockout protection)' });
        warning = `Your current IP (${myIp}) was not covered by the allowlist, so it was added automatically to prevent a lockout.`;
      } else if (body.kind === 'allow' && current.every((r) => r.kind !== 'allow')) {
        warning = 'Allowlist is now active: only IPs matching allow rules can access the workspace.';
      }
      const t = now();
      const id = crypto.randomUUID();
      const ins = db.prepare(`INSERT INTO ip_rules(id, kind, cidr, note, created_by, created_at) VALUES (?,?,?,?,?,?)`);
      db.transaction(() => {
        ins.run(id, body.kind, cidr, body.note ?? null, req.user!.id, t);
        for (const e of extra) ins.run(crypto.randomUUID(), e.kind, e.cidr, e.note, req.user!.id, t);
      })();
      ipRules.invalidate();
      ctx.audit(req, 'ip_rule_add', cidr, { kind: body.kind, note: body.note, autoAdded: extra.map((e) => e.cidr) });
      reply.code(201);
      return { rule: ruleDTO(db.prepare(`SELECT * FROM ip_rules WHERE id = ?`).get(id) as IpRuleRow), warning, rules: ipRules.list().map(ruleDTO) };
    });

    app.delete('/api/admin/ip-rules/:id', async (req) => {
      const id = (req.params as { id: string }).id;
      const current = ipRules.list();
      const rule = current.find((r) => r.id === id);
      if (!rule) throw notFound('Rule not found');
      const next = current.filter((r) => r.id !== id);
      if (!IpRules.wouldAllow(next, req.clientIp))
        throw new HttpError(400, 'self_lockout', `Removing this rule would lock out your own IP (${req.clientIp}).`);
      db.prepare(`DELETE FROM ip_rules WHERE id = ?`).run(id);
      ipRules.invalidate();
      ctx.audit(req, 'ip_rule_delete', rule.cidr, { kind: rule.kind });
      return { ok: true, rules: ipRules.list().map(ruleDTO) };
    });

    // ---------- runs ----------
    app.get('/api/admin/runs/active', async () => {
      ctx.runs.flushAll();
      return (
        db
          .prepare(
            `SELECT r.*, c.title AS conv_title, p.name AS project_name, p.slug AS project_slug, u.name AS user_name, u.email AS user_email,
                    (SELECT content FROM messages WHERE run_id = r.id AND role = 'user') AS prompt
             FROM runs r LEFT JOIN conversations c ON c.id = r.conversation_id LEFT JOIN projects p ON p.id = r.project_id
