    const settingsDTO = () => ({ ...settings.get(), claudeAuthToken: settings.maskedAuthToken() });
    app.get('/api/admin/settings', async () => settingsDTO());
    const putSettings = async (req: { body: unknown }) => {
      const body = settingsSchema.parse(req.body);
      const { claudeAuthToken, ...rest } = body;
      const merged = { ...settings.get(), ...Object.fromEntries(Object.entries(rest).filter(([, v]) => v !== undefined)) };
