    if (url.pathname === '/v2/preview/stop') {
      this.previewRunning = false;
      res.writeHead(200, { 'content-type': 'application/json' }).end('{"ok":true}');
      return;
    }
    if (url.pathname === '/v2/preview/status') {
      res.writeHead(200, { 'content-type': 'application/json' }).end(JSON.stringify({ running: this.previewRunning, port: null, pid: null, logTail: 'ok' }));
      return;
    }
    if (url.pathname === '/health') {
      res.writeHead(200, { 'content-type': 'application/json' }).end('{"status":"ok","version":"test"}');
      return;
    }
    res.writeHead(404).end();
  }
}

/** Tiny "dev server" upstream for preview proxy tests: echoes path + supports WebSocket. */
export async function startPreviewUpstream() {
  const server = http.createServer((req, res) => {
    if (req.url?.includes('redirect')) {
      res.writeHead(302, { location: `http://localhost:${(server.address() as AddressInfo).port}/preview/demo/next` }).end();
      return;
    }
    res.writeHead(200, { 'content-type': 'text/plain', 'x-frame-options': 'DENY' });
    res.end(`path=${req.url} host=${req.headers.host} cookie=${req.headers.cookie ?? ''}`);
  });
  const wss = new WebSocketServer({ server });
  wss.on('connection', (ws, req) => {
    ws.on('message', (m) => ws.send(`echo:${m.toString()}:${req.url}`));
  });
  await new Promise<void>((r) => server.listen(0, '127.0.0.1', r));
  const port = (server.address() as AddressInfo).port;
  return {
    port,
    close: async () => {
      wss.close();
      server.closeAllConnections();
      await new Promise<void>((r) => server.close(() => r()));
    },
  };
}

export interface TestEnv {
  built: BuiltApp;
  cfg: Config;
  fake: FakeClaudebox;
  dir: string;
  baseUrl: string;
  close: () => Promise<void>;
}

export async function makeEnv(overrides: Partial<Config> = {}, opts: { listen?: boolean } = {}): Promise<TestEnv> {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'nxeon-test-'));
  const fake = new FakeClaudebox();
  await fake.start();
  const webDist = path.join(dir, 'web');
  fs.mkdirSync(path.join(webDist, 'assets'), { recursive: true });
  fs.writeFileSync(path.join(webDist, 'index.html'), '<!doctype html><title>nx</title>');
  fs.writeFileSync(path.join(webDist, 'assets', 'app-abcdef12.js'), 'console.log(1)');
  const cfg = loadConfig({
    claudeboxUrl: fake.url,
    claudeboxApiKey: 'test-key',
    previewHost: '127.0.0.1',
    whisperUrl: 'http://127.0.0.1:1',
    projectsDir: path.join(dir, 'projects'),
    uploadsDir: path.join(dir, 'uploads'),
    dbPath: path.join(dir, 'db', 'nxeon.db'),
    sessionSecret: 'test-secret',
    adminEmail: 'admin@test.local',
    adminPassword: 'admin-password-1',
    adminName: 'Admin',
    trustProxy: ['127.0.0.1/32'],
    publicUrl: 'http://localhost',
    secureCookies: false,
    webDist,
    logLevel: 'error',
    ...overrides,
  });
  const built = await buildApp(cfg, { logger: false });
  let baseUrl = '';
  if (opts.listen) {
    await built.app.listen({ port: 0, host: '127.0.0.1' });
    baseUrl = `http://127.0.0.1:${(built.app.server.address() as AddressInfo).port}`;
  } else await built.app.ready();
  return {
    built, cfg, fake, dir, baseUrl,
    close: async () => {
      await built.close();
      await fake.stop();
      fs.rmSync(dir, { recursive: true, force: true });
    },
  };
}

export const XRW = { 'x-requested-with': 'nxeon' };

export async function login(env: TestEnv, email: string, password: string): Promise<string> {
  const res = await env.built.app.inject({ method: 'POST', url: '/api/auth/login', headers: XRW, payload: { email, password } });
  if (res.statusCode !== 200) throw new Error(`login failed ${res.statusCode} ${res.body}`);
  const c = res.cookies.find((x) => x.name === 'nx_sid');
  return `nx_sid=${c!.value}`;
}

export async function createUser(env: TestEnv, email: string, password: string, role: 'admin' | 'member' = 'member') {
  const id = crypto.randomUUID();
  env.built.ctx.db
    .prepare(`INSERT INTO users(id, email, name, password_hash, role, created_at) VALUES (?,?,?,?,?,?)`)
    .run(id, email, email.split('@')[0], await hashPassword(password), role, Date.now());
  return id;
}

export async function api(env: TestEnv, cookie: string, method: string, url: string, payload?: unknown) {
  const res = await env.built.app.inject({
    method: method as 'GET',
    url,
    headers: { cookie, ...(method === 'GET' ? {} : XRW) },
    ...(payload !== undefined ? { payload: payload as object } : {}),
  });
  let json: any = null;
  try {
    json = res.json();
  } catch {
    /* not json */
  }
  return { status: res.statusCode, json, res };
}

export async function waitFor<T>(fn: () => T | undefined | null | false, ms = 5000, step = 20): Promise<T> {
  const end = Date.now() + ms;
  for (;;) {
    const v = fn();
    if (v) return v;
    if (Date.now() > end) throw new Error('waitFor timed out');
    await new Promise((r) => setTimeout(r, step));
  }
}

export function openWs(env: TestEnv, cookie: string, pathname = '/ws'): Promise<{ ws: WebSocket; msgs: any[] }> {
  return new Promise((resolve, reject) => {
    const ws = new WebSocket(env.baseUrl.replace('http', 'ws') + pathname, { headers: { cookie } });
    const msgs: any[] = [];
    ws.on('message', (d) => {
      try {
        msgs.push(JSON.parse(d.toString()));
      } catch {
        msgs.push(d.toString());
      }
    });
    ws.on('open', () => resolve({ ws, msgs }));
    ws.on('error', reject);
    ws.on('unexpected-response', (_req, res) => reject(new Error(`ws status ${res.statusCode}`)));
  });
}

