    ];
    expect(out).toEqual([
      { id: '1', event: 'text', data: '{"delta":"a"}' },
      { id: '2', event: 'done', data: '{"exitCode":0}' },
    ]);
  });
  it('joins multi-line data', () => {
    const p = new SseParser();
    expect(p.push('data: a\ndata: b\n\n')).toEqual([{ id: undefined, event: 'message', data: 'a\nb' }]);
  });
});

describe('safe paths', () => {
  const root = fs.mkdtempSync(path.join(os.tmpdir(), 'nx-safe-'));
  const outside = fs.mkdtempSync(path.join(os.tmpdir(), 'nx-out-'));
  fs.mkdirSync(path.join(root, 'src'));
  fs.writeFileSync(path.join(root, 'src', 'a.txt'), 'x');
  fs.writeFileSync(path.join(outside, 'secret'), 's');
  fs.symlinkSync(outside, path.join(root, 'evil'));
  fs.symlinkSync(path.join(root, 'src'), path.join(root, 'goodlink'));

  it('cleans relative paths', () => {
    expect(cleanRel('/src/./a.txt')).toBe('src/a.txt');
    expect(cleanRel('src\\a.txt')).toBe('src/a.txt');
    expect(cleanRel('')).toBe('');
    expect(() => cleanRel('../etc/passwd')).toThrow();
    expect(() => cleanRel('src/../../x')).toThrow();
    expect(() => cleanRel('a\0b')).toThrow();
  });
  it('rejects symlink escapes', () => {
    expect(() => resolveSafe(root, 'evil/secret')).toThrow(/escapes/);
    expect(() => resolveSafe(root, 'evil')).toThrow(/escapes/);
    expect(() => resolveSafe(root, 'evil/new-file.txt')).toThrow(/escapes/);
    expect(resolveSafe(root, 'goodlink/a.txt').rel).toBe('goodlink/a.txt');
    expect(resolveSafe(root, 'src/new/deep.txt').rel).toBe('src/new/deep.txt');
  });
  it('sanitizes filenames and dispositions', () => {
    expect(sanitizeFilename('../../etc/passwd')).toBe('passwd');
    expect(sanitizeFilename('.htaccess')).toBe('_htaccess');
    expect(sanitizeFilename('a"b<c>.txt')).toBe('a_b_c_.txt');
    expect(contentDisposition('inline', 'naïve "x".png')).toBe(`inline; filename="na_ve _x_.png"; filename*=UTF-8''na%C3%AFve%20%22x%22.png`);
  });
  it('detects binary', () => {
    expect(looksBinary(Buffer.from('hello ✓'))).toBe(false);
    expect(looksBinary(Buffer.from([0x89, 0x50, 0x4e, 0x47, 0, 1]))).toBe(true);
    expect(looksBinary(Buffer.from([0xff, 0xfe, 0xfd]))).toBe(true);
  });
});

describe('ip + misc', () => {
  it('cidr matching', () => {
    expect(parseCidr('10.0.0.0/8')).toEqual({ family: 'ipv4', address: '10.0.0.0', prefix: 8 });
    expect(parseCidr('10.0.0.0/33')).toBeNull();
    expect(parseCidr('nope')).toBeNull();
    const bl = makeBlockList(['10.0.0.0/8', '2001:db8::/32']);
    expect(ipInList(bl, '10.1.2.3')).toBe(true);
    expect(ipInList(bl, '::ffff:10.1.2.3')).toBe(true);
    expect(ipInList(bl, '11.0.0.1')).toBe(false);
    expect(ipInList(bl, '2001:db8::1')).toBe(true);
    expect(normalizeIp('::ffff:127.0.0.1')).toBe('127.0.0.1');
  });
  it('titles and slugs', () => {
    expect(autoTitle('  build me a **todo** app with `react`  ')).toBe('Build me a todo app with react');
    expect(autoTitle('x'.repeat(100)).length).toBeLessThanOrEqual(61);
    expect(autoTitle('```\ncode\n```')).toBe('New conversation');
    expect(slugify('My Cool App!')).toBe('my-cool-app');
    expect(slugify('Ünïcode Ñame')).toBe('unicode-name');
    expect(slugify('!!!')).toMatch(/^project-[0-9a-f]{6}$/);
  });
});
