import { afterAll, beforeAll, describe, expect, it } from 'vitest';
import { api, createUser, login, makeEnv, XRW, type TestEnv } from './helpers.js';

let env: TestEnv;
beforeAll(async () => {
  env = await makeEnv();
});
afterAll(async () => env.close());

describe('auth', () => {
  it('rejects bad credentials and accepts admin bootstrap', async () => {
    const bad = await env.built.app.inject({ method: 'POST', url: '/api/auth/login', headers: XRW, payload: { email: 'admin@test.local', password: 'nope' } });
    expect(bad.statusCode).toBe(401);
    expect(bad.json().error.code).toBe('invalid_credentials');
    const ok = await env.built.app.inject({ method: 'POST', url: '/api/auth/login', headers: XRW, payload: { email: 'ADMIN@test.local', password: 'admin-password-1' } });
    expect(ok.statusCode).toBe(200);
    expect(ok.json().user).toMatchObject({ email: 'admin@test.local', role: 'admin' });
    const cookie = ok.cookies.find((c) => c.name === 'nx_sid')!;
    expect(cookie.httpOnly).toBe(true);
    expect(cookie.sameSite).toBe('Lax');
    const me = await api(env, `nx_sid=${cookie.value}`, 'GET', '/api/auth/me');
    expect(me.status).toBe(200);
    expect(me.json.user.email).toBe('admin@test.local');
    expect(me.json.user).not.toHaveProperty('password_hash');
  });

  it('requires X-Requested-With on mutating requests', async () => {
    const r = await env.built.app.inject({ method: 'POST', url: '/api/auth/login', payload: { email: 'a@b.c', password: 'x' } });
    expect(r.statusCode).toBe(403);
    expect(r.json().error.code).toBe('csrf');
    const r2 = await env.built.app.inject({ method: 'POST', url: '/api/auth/login', headers: { ...XRW, origin: 'https://evil.example' }, payload: { email: 'a@b.c', password: 'x' } });
    expect(r2.statusCode).toBe(403);
  });

  it('401 without session; error envelope', async () => {
    const r = await env.built.app.inject({ method: 'GET', url: '/api/projects' });
    expect(r.statusCode).toBe(401);
    expect(r.json()).toEqual({ error: { code: 'unauthorized', message: 'Not signed in' } });
    const nf = await env.built.app.inject({ method: 'GET', url: '/api/nope' });
    expect(nf.statusCode).toBe(404);
    expect(nf.json().error.code).toBe('not_found');
  });

  it('locks out after repeated failures', async () => {
    await createUser(env, 'lock@test.local', 'right-password');
    for (let i = 0; i < 5; i++) {
      const r = await env.built.app.inject({ method: 'POST', url: '/api/auth/login', headers: { ...XRW, 'x-forwarded-for': `10.9.0.${i}` }, payload: { email: 'lock@test.local', password: 'wrong' } });
      expect(r.statusCode).toBe(401);
    }
    const r = await env.built.app.inject({ method: 'POST', url: '/api/auth/login', headers: { ...XRW, 'x-forwarded-for': '10.9.1.1' }, payload: { email: 'lock@test.local', password: 'right-password' } });
    expect(r.statusCode).toBe(401);
    expect(r.json().error.code).toBe('locked');
  });

  it('rate limits login per IP', async () => {
    let last = 0;
    for (let i = 0; i < 12; i++) {
      const r = await env.built.app.inject({ method: 'POST', url: '/api/auth/login', headers: { ...XRW, 'x-forwarded-for': '10.8.8.8' }, payload: { email: 'nobody@test.local', password: 'x' } });
      last = r.statusCode;
    }
    expect(last).toBe(429);
  });

  it('logout invalidates the session; password change works', async () => {
    await createUser(env, 'pw@test.local', 'old-password');
    const cookie = await login(env, 'pw@test.local', 'old-password');
    const bad = await api(env, cookie, 'POST', '/api/auth/password', { currentPassword: 'wrong', newPassword: 'new-password-1' });
    expect(bad.status).toBe(400);
    const ok = await api(env, cookie, 'POST', '/api/auth/password', { currentPassword: 'old-password', newPassword: 'new-password-1' });
