import { afterAll, beforeAll, describe, expect, it } from 'vitest';
import { api, createUser, login, makeEnv, openWs, waitFor, type TestEnv } from './helpers.js';

let env: TestEnv;
let alice: string;
let project: any;

beforeAll(async () => {
  env = await makeEnv({}, { listen: true });
  await createUser(env, 'alice@test.local', 'alice-pass');
  alice = await login(env, 'alice@test.local', 'alice-pass');
  project = (await api(env, alice, 'POST', '/api/projects', { name: 'Runner' })).json;
});
afterAll(async () => env.close());

const runStatus = (id: string) => (env.built.ctx.db.prepare('SELECT status FROM runs WHERE id = ?').get(id) as any)?.status;
const isFinal = (s: string) => ['done', 'error', 'aborted'].includes(s);

async function newConv() {
  return (await api(env, alice, 'POST', `/api/projects/${project.id}/conversations`, {})).json;
}

describe('runs', () => {
  it('streams a run over WS, persists events, strips suggestions', async () => {
    const conv = await newConv();
    expect(conv.title).toBe('New conversation');
    const { ws, msgs } = await openWs(env, alice);
    ws.send(JSON.stringify({ t: 'sub_project', projectId: project.id }));
    const r = await api(env, alice, 'POST', `/api/conversations/${conv.id}/prompt`, { text: 'Build a **todo** app please', attachments: [], model: 'sonnet', mode: 'edit', thinking: 'max' });
    expect(r.status).toBe(200);
    const { runId, messageId } = r.json;
    ws.send(JSON.stringify({ t: 'sub', runId, fromSeq: 0 }));
    await waitFor(() => isFinal(runStatus(runId)));
    await waitFor(() => msgs.some((m) => m.t === 'suggestions'));
    expect(runStatus(runId)).toBe('done');

    // upstream request body
    const body = env.fake.bodies.at(-1)!;
    expect(body).toMatchObject({ runId, prompt: 'Build a **todo** app please', projectSlug: 'runner', sessionId: null, model: 'sonnet', mode: 'edit', thinking: 'max', previewPort: 4100, maxTurns: 50 });
    expect(String(body.appendSystemPrompt)).toContain('<nx-suggestions>');
    expect(String(body.appendSystemPrompt)).toContain('/preview/runner/');
    expect(String(body.appendSystemPrompt)).toContain('0.0.0.0');
    expect(body).not.toHaveProperty('authToken');

    // live events: seq strictly increasing, no suggestion markup leaked
    const evs = msgs.filter((m) => m.t === 'run_event' && m.runId === runId);
    const seqs = evs.map((e) => e.seq);
    expect(seqs).toEqual([...seqs].sort((a, b) => a - b));
    expect(new Set(seqs).size).toBe(seqs.length);
    const liveText = evs.filter((e) => e.type === 'text').map((e) => e.data.delta).join('');
    expect(liveText).toBe('Hello world.\n\n');
    expect(JSON.stringify(evs)).not.toContain('nx-sugg');
    expect(evs.at(-1).type).toBe('done');
    const sugg = msgs.find((m) => m.t === 'suggestions');
    expect(sugg.items).toEqual([
      { label: 'Run tests', prompt: 'npm test', kind: 'test' },
      { label: 'Next', prompt: 'do next', kind: 'next' },
    ]);
    expect(msgs.some((m) => m.t === 'run_status' && m.runId === runId && m.status === 'running')).toBe(true);
    expect(msgs.some((m) => m.t === 'run_status' && m.runId === runId && m.status === 'done')).toBe(true);
    expect(msgs.some((m) => m.t === 'graph_pulse' && m.projectId === project.id)).toBe(true);

    // REST: messages with run + events + suggestions; conversation titled + session id
    const list = (await api(env, alice, 'GET', `/api/conversations/${conv.id}/messages`)).json;
    expect(list).toHaveLength(2);
    expect(list[0]).toMatchObject({ id: messageId, role: 'user', content: 'Build a **todo** app please', attachments: [], runId, userName: 'alice' });
    expect(list[1]).toMatchObject({ role: 'assistant', content: 'Hello world.', runId });
    expect(list[1].run).toMatchObject({ id: runId, status: 'done', model: 'sonnet', mode: 'edit', inputTokens: 150, outputTokens: 40, cacheRead: 5, cacheWrite: 1, costUsd: 0.0123, durationMs: 1234 });
    expect(list[1].suggestions).toHaveLength(2);
    expect(list[1].events.map((e: any) => e.seq)).toEqual(seqs);
    const c2 = (await api(env, alice, 'GET', `/api/conversations/${conv.id}`)).json;
    expect(c2).toMatchObject({ title: 'Build a todo app please', claudeSessionId: 'sess-1', model: 'sonnet', mode: 'edit' });

    // WS replay from a later seq after the run finished
    const { ws: ws2, msgs: m2 } = await openWs(env, alice);
    ws2.send(JSON.stringify({ t: 'sub', runId, fromSeq: 5 }));
    await waitFor(() => m2.some((m) => m.t === 'suggestions'));
    const replay = m2.filter((m) => m.t === 'run_event');
    expect(replay[0].seq).toBe(5);
    expect(replay.map((e) => e.seq)).toEqual(seqs.filter((s) => s >= 5));
    expect(m2.find((m) => m.t === 'run_status')).toMatchObject({ runId, status: 'done', projectId: project.id, conversationId: conv.id });
    ws2.send(JSON.stringify({ t: 'ping' }));
    await waitFor(() => m2.some((m) => m.t === 'pong'));
    ws.close();
    ws2.close();

    // second prompt resumes the session
    const r2 = await api(env, alice, 'POST', `/api/conversations/${conv.id}/prompt`, { text: 'again', attachments: [], model: 'sonnet', mode: 'auto', thinking: 'off' });
    await waitFor(() => isFinal(runStatus(r2.json.runId)));
    expect(env.fake.bodies.at(-1)!.sessionId).toBe('sess-1');
    // usage
    const usage = (await api(env, alice, 'GET', '/api/usage/me')).json;
    expect(usage.today).toMatchObject({ inputTokens: 300, outputTokens: 80, runs: 2 });
    expect(usage.byModel[0]).toMatchObject({ model: 'sonnet', tokens: 380, runs: 2 });
    expect(usage.limits.dailyTokens).toBeNull();
  });

  it('re-attaches when the upstream stream drops mid-run', async () => {
    const conv = await newConv();
    const r = await api(env, alice, 'POST', `/api/conversations/${conv.id}/prompt`, { text: '[drop] go', attachments: [], model: 'opus', mode: 'auto', thinking: 'normal' });
    await waitFor(() => isFinal(runStatus(r.json.runId)), 10000);
    expect(runStatus(r.json.runId)).toBe('done');
    const list = (await api(env, alice, 'GET', `/api/conversations/${conv.id}/messages`)).json;
    expect(list[1].content).toBe('Hello world.');
    const types = list[1].events.map((e: any) => e.type);
    expect(types.filter((t: string) => t === 'tool_use')).toHaveLength(1); // no duplicates after reattach
    expect(types.at(-1)).toBe('done');
  });

  it('aborts a running run', async () => {
    const conv = await newConv();
    const r = await api(env, alice, 'POST', `/api/conversations/${conv.id}/prompt`, { text: '[hold] wait', attachments: [], model: 'opus', mode: 'auto', thinking: 'normal' });
    const runId = r.json.runId;
    await waitFor(() => runStatus(runId) === 'running');
    await waitFor(() => env.fake.runs.get(runId)?.waiters.size);
    const busy = await api(env, alice, 'POST', `/api/conversations/${conv.id}/prompt`, { text: 'x', attachments: [], model: 'opus', mode: 'auto', thinking: 'normal' });
    expect(busy.status).toBe(409);
