import fs from 'node:fs';
import path from 'node:path';
import sharp from 'sharp';
import { afterAll, beforeAll, describe, expect, it } from 'vitest';
import { WebSocket } from 'ws';
import { buildApp } from '../src/app.js';
import { api, createUser, login, makeEnv, startPreviewUpstream, waitFor, XRW, type TestEnv } from './helpers.js';

let env: TestEnv;
let upstream: Awaited<ReturnType<typeof startPreviewUpstream>>;
let alice: string, bob: string;
let project: any;

beforeAll(async () => {
  upstream = await startPreviewUpstream();
  env = await makeEnv({ previewPortMin: upstream.port, previewPortMax: upstream.port + 3 }, { listen: true });
  await createUser(env, 'alice@test.local', 'alice-pass');
  await createUser(env, 'bob@test.local', 'bob-pass');
  alice = await login(env, 'alice@test.local', 'alice-pass');
  bob = await login(env, 'bob@test.local', 'bob-pass');
  project = (await api(env, alice, 'POST', '/api/projects', { name: 'Demo' })).json;
  expect(project.previewPort).toBe(upstream.port);
});
afterAll(async () => {
  await env.close();
  await upstream.close();
});

describe('preview', () => {
  it('controls preview via claudebox', async () => {
    const st = (await api(env, alice, 'GET', `/api/projects/${project.id}/preview/status`)).json;
    expect(st).toMatchObject({ running: false, url: '/preview/demo/', logTail: 'line1\nline2', port: upstream.port });
    expect((await api(env, bob, 'POST', `/api/projects/${project.id}/preview/start`)).status).toBe(404);
    const s = (await api(env, alice, 'POST', `/api/projects/${project.id}/preview/start`)).json;
    expect(s.running).toBe(true);
    expect((await api(env, alice, 'POST', `/api/projects/${project.id}/preview/stop`)).json.running).toBe(false);
  });

  it('proxies HTTP keeping the prefix, strips our cookie, auth-checks', async () => {
    const res = await fetch(`${env.baseUrl}/preview/demo/src/main.ts?x=1`, { headers: { cookie: `${alice}; theme=dark` } });
    expect(res.status).toBe(200);
    const body = await res.text();
    expect(body).toContain('path=/preview/demo/src/main.ts?x=1');
    expect(body).toContain(`host=127.0.0.1:${upstream.port}`);
    expect(body).toContain('cookie=theme=dark');
    expect(body).not.toContain('nx_sid');
    expect(res.headers.get('x-frame-options')).toBeNull();
    expect(res.headers.get('content-security-policy')).toBe("frame-ancestors 'self'");
    expect((await fetch(`${env.baseUrl}/preview/demo/`)).status).toBe(401);
    expect((await fetch(`${env.baseUrl}/preview/demo/`, { headers: { cookie: bob } })).status).toBe(404);
    const redir = await fetch(`${env.baseUrl}/preview/demo`, { headers: { cookie: alice }, redirect: 'manual' });
    expect(redir.status).toBe(302);
    expect(redir.headers.get('location')).toBe('/preview/demo/');
    const r2 = await fetch(`${env.baseUrl}/preview/demo/redirect`, { headers: { cookie: alice }, redirect: 'manual' });
    expect(r2.headers.get('location')).toBe('/preview/demo/next');
    // POST bodies stream through
    const post = await fetch(`${env.baseUrl}/preview/demo/api`, { method: 'POST', headers: { cookie: alice, 'content-type': 'application/json' }, body: '{"a":1}' });
    expect(post.status).toBe(200);
  });

  it('strip mode removes the prefix', async () => {
    await api(env, alice, 'PATCH', `/api/projects/${project.id}`, { previewStrip: true });
    const body = await (await fetch(`${env.baseUrl}/preview/demo/hello`, { headers: { cookie: alice } })).text();
    expect(body).toContain('path=/hello ');
    await api(env, alice, 'PATCH', `/api/projects/${project.id}`, { previewStrip: false });
  });

  it('proxies websocket upgrades (HMR)', async () => {
    const ws = new WebSocket(`${env.baseUrl.replace('http', 'ws')}/preview/demo/__hmr?token=abc`, { headers: { cookie: alice } });
    const got = await new Promise<string>((resolve, reject) => {
      ws.on('open', () => ws.send('ping'));
      ws.on('message', (m) => resolve(m.toString()));
      ws.on('error', reject);
    });
    expect(got).toBe('echo:ping:/preview/demo/__hmr?token=abc');
